import json, pathlib, re
ROOT=pathlib.Path('/mnt/data/cvhs_complete/src/assessments')
ROOT.mkdir(parents=True, exist_ok=True)
chapters={}

def Q(prompt, choices, correct, explanation, topic, section, difficulty='application', qtype='scenario'):
    return dict(prompt=prompt, choices=choices, correctIndex=correct, explanation=explanation, topic=topic, section=section, difficulty=difficulty, type=qtype)

chapters[1]=[
Q('A student is planning a first solo cross-country and wants to know what is legally required, what procedures are recommended, and what standards will later be evaluated on the practical test. Which set of sources best separates those three purposes?', ['14 CFR for legal requirements, AIM/FAA guidance for recommended procedures, and the current ACS for practical-test standards','The POH for legal requirements, sectional chart for recommended procedures, and NOTAMs for practical-test standards','The AIM for legal requirements, 14 CFR for recommended procedures, and a flight-school checklist for practical-test standards','A CFI lesson plan for legal requirements, the POH for recommended procedures, and ATIS for practical-test standards'],0,'14 CFR contains binding federal aviation regulations; the AIM and other FAA guidance describe procedures and operating information; the current Airman Certification Standards define the knowledge, risk-management, and skill elements evaluated on the practical test.','FAA sources','Regulations, guidance, and standards'),
Q('A pilot notices that a flight-school checklist conflicts with an operating limitation in the airplane flight manual. Which source controls the operation of that airplane?', ['The flight-school checklist because it is tailored to local operations','The airplane\'s approved limitations and operating information','Whichever source was published most recently','The checklist if an instructor signed it'],1,'Aircraft-specific approved limitations and operating information cannot be overridden by a local checklist or instructor preference.','Aircraft documents','Aircraft-specific operating authority'),
Q('During preflight planning, a pilot finds a current NOTAM closing the destination runway that is shown open on the sectional chart. What is the correct conclusion?', ['The sectional chart controls because it is an FAA publication','The NOTAM provides current time-sensitive information and must be considered','The runway may be used if weather is VFR','The closure applies only to IFR flights'],1,'NOTAMs communicate time-critical aeronautical information that may temporarily supersede what appears on a chart or in other publications.','Aeronautical publications','NOTAMs'),
Q('A student has passed the FAA knowledge test but has not received the required flight training or endorsements for solo flight. What privilege did the test result itself create?', ['Authority to act as PIC on local solo flights','Authority to fly solo only in the traffic pattern','No solo-flight privilege by itself','Authority to carry one passenger with instructor approval'],2,'Passing a knowledge test demonstrates knowledge; solo privileges depend on the applicable eligibility, training, proficiency, and instructor-endorsement requirements.','Pilot training','Knowledge versus flight privileges'),
Q('A student has logged the regulatory minimum flight experience for a certificate but still requires frequent instructor intervention on landings. What is the strongest reason the instructor should delay the practical-test endorsement?', ['Minimum hours are only eligibility thresholds; proficiency and judgment must also be demonstrated','A practical test may not be taken until twice the minimum hours are logged','The DPE, not the instructor, decides whether the applicant is prepared before the endorsement','Landings are not part of practical-test preparation'],0,'Minimum aeronautical experience does not by itself establish practical-test readiness. The instructor is responsible for recommending an applicant who demonstrates the required knowledge, risk management, and skill.','Flight training','Proficiency versus minimum experience'),
Q('An applicant is preparing for a private pilot practical test. Which document most directly tells the applicant what knowledge, risk-management, and flight-skill elements the evaluator will assess?', ['The current Airman Certification Standards for the certificate and rating sought','The airport Chart Supplement','A current sectional chart','The aircraft maintenance records'],0,'The ACS organizes the areas of operation and tasks used to evaluate an applicant on the practical test.','Certification','Airman Certification Standards'),
Q('A student asks why a CFI emphasizes checklists, collision avoidance, runway-incursion prevention, positive exchange of flight controls, and workload management from the first lesson. What is the best explanation?', ['These habits are primarily designed to make the practical test shorter','They are operational safety behaviors that should be learned as normal pilot behavior, not added only at the end of training','They are required only for commercial pilots','They replace the need for aircraft-specific procedures'],1,'The handbook emphasizes that safe operating habits are learned behaviors that instructors should reinforce throughout training.','Safety culture','Operational safety habits'),
Q('Two airplanes are both certificated as airplanes, but one is single-engine land and the other multiengine sea. Which terminology correctly distinguishes them?', ['Airplane is the category; single-engine land and multiengine sea are classes','Airplane is the class; land and sea are categories','Single-engine and multiengine are types in every case','Land and sea are ratings only for instructors'],0,'For pilot certification, airplane is a category; single-engine land, multiengine land, single-engine sea, and multiengine sea are examples of airplane classes.','Aircraft classification','Category and class'),
Q('A pilot is qualified in a small single-engine piston airplane and is offered a flight in an aircraft for which a specific type rating is required. What should the pilot infer?', ['Category and class privileges automatically include every aircraft of that class','A required type rating is an additional qualification for that specific aircraft type','A type rating is only a maintenance designation','A logbook endorsement from any pilot replaces a type rating'],1,'Some aircraft require a specific type rating in addition to category and class qualifications.','Aircraft classification','Type ratings'),
Q('A student wants to use a smartphone summary of regulations rather than checking the current regulation itself before a flight. What is the principal risk?', ['Smartphone screens cannot display legal text accurately','Summaries may omit conditions, exceptions, or changes that determine whether an operation is legal','FAA regulations apply only when printed on paper','Only a DPE may interpret regulations'],1,'Secondary summaries can be useful study aids but are not substitutes for checking the current regulatory text and its conditions.','FAA sources','Current regulations'),
Q('A pilot wants a concise source for basic ATC procedures, airport operations, and operating practices in the National Airspace System. Which source is most appropriate?', ['Aeronautical Information Manual','Aircraft registration certificate','Type Certificate Data Sheet','Weight-and-balance equipment list'],0,'The AIM is the FAA\'s basic information manual for operating in the National Airspace System, including ATC procedures and related operating information.','Aeronautical publications','AIM'),
Q('A student sees an FAA Advisory Circular describing an acceptable procedure. How should the student normally interpret an AC unless it has been incorporated into a regulation or approval?', ['As binding law equivalent to 14 CFR','As FAA guidance and information, often describing acceptable means of compliance','As aircraft-specific operating limitations','As a temporary flight restriction'],1,'Advisory Circulars generally provide guidance, information, and acceptable methods rather than independently creating regulatory requirements.','Aeronautical publications','Advisory Circulars'),
Q('A flight instructor demonstrates a maneuver, transfers control to the student, and later takes the controls back. Which practice most directly prevents both pilots from believing the other is flying?', ['Rely on control movement to show who has control','Use an explicit positive exchange of controls with verbal acknowledgment','Have the student keep one hand off the controls','Let the person in the left seat always remain in control'],1,'A positive exchange of controls makes the transfer unambiguous and reduces the risk of either dual input or nobody controlling the airplane.','Flight training','Positive exchange of controls'),
Q('Why is scenario-based training valuable compared with memorizing isolated facts?', ['It removes the need to learn regulations','It requires the student to integrate knowledge, risk management, and decisions in realistic flight situations','It guarantees every future flight will match a practiced scenario','It allows the student to skip aircraft-specific training'],1,'Scenario-based training develops the ability to apply knowledge and make decisions in realistic contexts rather than merely recall definitions.','Flight training','Scenario-based training'),
Q('A student is choosing between two instructors. One focuses only on maneuver tolerances; the other also teaches weather decisions, risk management, checklist discipline, and aircraft limitations. Which approach better matches the FAA concept of training the “total” pilot?', ['The first, because practical tests evaluate only stick-and-rudder accuracy','The second, because competent pilot performance integrates knowledge, judgment, risk management, and skill','Either, because instructors do not influence safety habits','The first, because weather and risk management are learned only after certification'],1,'The handbook describes the goal of training the total pilot, not merely rehearsing isolated maneuvers.','Flight training','Total-pilot concept'),
Q('A student asks what role a Designated Pilot Examiner normally serves in the certification process. Which answer is most accurate?', ['Provides the applicant\'s primary flight instruction','Conducts authorized FAA practical tests and certification tasks within the examiner\'s designation','Issues aircraft airworthiness certificates after maintenance','Approves every student solo flight'],1,'A DPE is delegated authority to conduct specified practical tests and related certification functions on behalf of the FAA.','Certification','DPE role'),
Q('A student receives an instructor endorsement for a specific training privilege. What is the best interpretation of that endorsement?', ['It replaces all applicable regulations for that operation','It documents that an authorized instructor has made the required certification or recommendation for the specified privilege or test','It is equivalent to a pilot certificate','It remains valid for every aircraft and operation without limitation'],1,'Instructor endorsements document specific training, proficiency, or recommendations required by regulation; their scope and validity depend on the applicable requirement.','Certification','Instructor endorsements'),
Q('A student believes the FAA practical test is intended to sample every possible situation a pilot may encounter. Why is that belief unsafe?', ['The test is a limited evaluation; certification does not eliminate the need for continued learning and conservative judgment','The practical test evaluates only aircraft paperwork','The test contains no risk-management elements','Passing the test removes the need for recurrent training'],0,'A practical test samples required knowledge, risk management, and skill in a limited period. Safe pilots continue learning and maintain proficiency after certification.','Certification','Practical-test purpose'),
Q('Which statement best distinguishes a pilot certificate from an aircraft airworthiness certificate?', ['The pilot certificate establishes a person\'s airman privileges; the airworthiness certificate is part of the aircraft\'s authorization to operate when maintained and operated as required','Both documents certify the pilot\'s medical fitness','The pilot certificate belongs to the aircraft and the airworthiness certificate belongs to the pilot','They are interchangeable if both are carried aboard'],0,'Airman certification concerns the person\'s privileges; airworthiness certification concerns the aircraft.','Certification','Pilot versus aircraft certification'),
Q('A new pilot wants to know whether a training airplane may be operated with a particular piece of equipment inoperative. Which approach is most appropriate?', ['Assume it is safe if the airplane starts','Consult the aircraft documents and applicable regulations, then follow the authorized inoperative-equipment process','Ask another student whether they have flown it that way','Use the AIM alone because it supersedes aircraft limitations'],1,'Legality and safety of inoperative equipment depend on aircraft-specific requirements and applicable regulations; informal experience does not establish airworthiness.','FAA sources','Aircraft-specific legality'),
Q('A pilot learns a procedure from an online forum that conflicts with the current AIM and the airplane POH. What should the pilot do?', ['Use the forum procedure if several pilots agree with it','Verify the operation using current authoritative FAA and aircraft-specific sources','Average the two procedures','Use whichever procedure is faster'],1,'Authoritative current sources should be used to verify procedures; informal online advice can be incomplete or wrong.','FAA sources','Source reliability'),
Q('A student is learning to operate at an unfamiliar airport. Which combination best reflects sound use of FAA information before flight?', ['Sectional chart only','Chart, Chart Supplement, current NOTAMs, weather information, and applicable airport procedures','A social-media airport review and GPS map','Only the runway length listed in the POH'],1,'Safe preflight preparation combines charted information with current airport/facility data, NOTAMs, weather, and procedures.','Aeronautical publications','Preflight information'),
Q('A student asks why the FAA emphasizes both knowledge and risk management in addition to physical control of the airplane. What is the best answer?', ['Most accidents occur because pilots cannot physically move the controls','Safe flight requires correct decisions about whether, when, and how to use aircraft capabilities, not just the ability to manipulate controls','Risk management matters only to airline crews','Knowledge becomes unnecessary once a pilot can land consistently'],1,'Pilot competency includes deciding how to apply aircraft capability within limitations and conditions; stick-and-rudder skill alone is insufficient.','Safety culture','Integrated pilot competency'),
Q('A pilot is unsure whether an FAA publication is current. What is the safest action before relying on it for a flight decision?', ['Assume the copy is current if it looks official','Verify the current edition or revision through an authoritative FAA source and check time-sensitive updates','Use the oldest version because it is more established','Ask a passenger to choose'],1,'Aviation information changes. Pilots should verify currency and check applicable updates rather than rely on appearance alone.','FAA sources','Publication currency'),
Q('A student asks what is meant by “pilot in command.” Which idea is operationally most important?', ['The PIC is the person who sits in the left seat','The PIC is the person who has final authority and responsibility for the operation and safety of the flight under the applicable rules','The PIC is always the aircraft owner','The PIC is whichever person is manipulating the controls at every moment'],1,'PIC status is about legal authority and responsibility, not simply seat position or moment-to-moment control manipulation.','Certification','PIC responsibility'),
Q('During training, a student becomes fixated on passing the written test and neglects cockpit procedures. Which correction best aligns with safe pilot development?', ['Continue because knowledge-test performance predicts flight skill','Integrate study with supervised flight training, aircraft-specific procedures, and scenario-based decision-making','Delay all ground study until after solo','Replace instruction with practice-question memorization'],1,'Ground knowledge supports flight operations, but competency develops by integrating knowledge with supervised skill, procedures, and judgment.','Flight training','Integrating ground and flight training'),
Q('Why should a pilot learn how to locate information in FAA publications rather than merely memorize a set of rules?', ['Rules and operational information can change, and pilots must be able to verify the current requirement or procedure','Memorization is prohibited by the FAA','Publications are used only during practical tests','A pilot may ignore regulations that are difficult to locate'],0,'A pilot needs durable information-management skills because regulations, procedures, charts, and notices are revised over time.','FAA sources','Information management'),
Q('A student wants to know whether a proposed flight is within the privileges and limitations of a particular pilot certificate. What should be checked first?', ['Current 14 CFR provisions governing that certificate and operation','The aircraft paint scheme','A generic aviation blog','The last practical-test score'],0,'Pilot privileges and limitations are established by the applicable regulations and any certificate-specific limitations or endorsements.','Certification','Privileges and limitations'),
Q('A pilot completes a practical test successfully. Which mindset best supports long-term safety?', ['The certificate proves the pilot is prepared for every condition the aircraft can encounter','Certification establishes a minimum demonstrated standard; the pilot must continue building proficiency, judgment, and experience','Further instruction should be avoided because it can create dependence','Only regulatory changes require future study'],1,'Certification is a milestone, not the end of learning. Continued proficiency, recurrent training, and conservative judgment remain essential.','Safety culture','Continued learning'),
Q('A student is asked to explain the path from first lesson to pilot certification. Which sequence best captures the relationship among knowledge, training, endorsements, testing, and certification?', ['Study alone leads directly to certification once the knowledge test is passed','Ground knowledge and flight training develop together; required experience and endorsements establish eligibility; knowledge and practical tests verify standards before certification','Solo flight must occur before any ground study','The DPE provides all required training during the practical test'],1,'Pilot development normally integrates ground and flight training; eligibility requires applicable experience and endorsements, and certification follows successful completion of required testing.','Flight training','Training pathway')
]

chapters[2]=[
Q('A VFR pilot has planned a mountain cross-country. The weather is legal but hazy, the pilot has little mountain experience, and an important meeting creates pressure to arrive. Which risk-management action best addresses the whole situation?', ['Focus only on whether visibility meets the regulatory minimum','Evaluate pilot, aircraft, environment, and external pressures together and choose a safer alternative if the combined risk is unacceptable','Depart because each individual risk is manageable by itself','Ignore the meeting pressure because it is not an aviation hazard'],1,'The PAVE framework is designed to consider interacting risks. Legal weather does not make the total risk acceptable when experience, terrain, visibility, and external pressure combine.','Risk management','PAVE checklist'),
Q('A pilot notices lowering ceilings ahead and thinks, “I have already flown this far, so I should keep going.” Which decision error is most important to recognize?', ['A sunk-cost or continuation bias reinforced by external pressure','A failure of the pitot-static system','A navigation database error','A weight-and-balance calculation error'],0,'Past time or effort does not improve future weather. Good ADM reassesses the current situation and preserves safe alternatives.','ADM','Continuation bias'),
Q('A pilot says, “The rules are overly cautious; I know what I can get away with.” Which hazardous attitude is being demonstrated, and what is the useful antidote?', ['Macho — taking chances is foolish','Anti-authority — follow the rules; they are usually right','Invulnerability — it could happen to me','Resignation — I am not helpless'],1,'Anti-authority is the tendency to disregard rules or procedures. Its antidote is to recognize that the rules are usually right and exist for a reason.','Human factors','Hazardous attitudes'),
Q('A pilot receives a last-minute reroute while hand-flying in turbulence and begins entering it into the GPS with head down. What is the best ADM response?', ['Continue programming because automation always reduces workload','Stabilize the airplane, manage workload, use available resources, and delay or simplify programming until it can be done safely','Turn off all avionics','Accept any route without understanding it'],1,'Aviate first and manage automation deliberately. Programming at a high-workload moment can create fixation and loss of situational awareness.','Single-pilot resource management','Automation management'),
Q('A pilot identifies thunderstorms along the direct route. In the 3P model, what does “Process” require?', ['Only noticing that thunderstorms exist','Evaluating how the hazard affects the safety of this specific flight','Immediately selecting the first alternate route','Recording the hazard after landing'],1,'Perceive identifies the hazard; Process evaluates its impact; Perform implements a course of action.','ADM models','3P model'),
Q('After evaluating a risk, a pilot decides to delay departure until a front passes. In the 3P model, this is primarily which step?', ['Perceive','Process','Perform','Program'],2,'Choosing and implementing a safer course of action is the Perform step.','ADM models','3P model'),
Q('A pilot is tempted to depart with a known maintenance discrepancy because “it will probably be fine.” Which part of the CARE checklist most directly challenges that rationalization?', ['Consequences and Reality','Automation and Range','Regulations and Endurance','Communication and Equipment'],0,'CARE asks the pilot to examine Consequences, Alternatives, Reality, and External factors. “Probably fine” should trigger a realistic reassessment of the actual hazard and consequences.','Risk management','CARE checklist'),
Q('A pilot recognizes a hazard that cannot be eliminated and chooses a route that keeps the airplane near suitable diversion airports. Under TEAM, what risk-control strategy is this?', ['Transfer','Eliminate','Accept without change','Mitigate'],3,'Changing the route to reduce exposure or consequences is mitigation.','Risk management','TEAM checklist'),
Q('A pilot is fatigued, mildly ill, and taking a new medication. The airplane and weather are excellent. Why can the overall flight still be unacceptable?', ['The PAVE model treats pilot condition as a major risk category that can independently make a flight unsafe','Good weather automatically compensates for pilot condition','Medication matters only above 10,000 feet','Fatigue is relevant only at night'],0,'Pilot fitness is one of the core PAVE categories. Excellent aircraft and weather do not cancel impaired judgment or performance.','Risk management','PAVE — Pilot'),
Q('A pilot thinks, “I have flown in worse weather and nothing happened, so this will be fine.” Which hazardous attitude is most evident?', ['Impulsivity','Invulnerability','Resignation','Anti-authority'],1,'Invulnerability is the belief that accidents happen to others rather than oneself; prior success does not eliminate current risk.','Human factors','Hazardous attitudes'),
Q('A pilot is behind schedule and makes a quick fuel decision without checking the numbers because “we need to go now.” Which hazardous attitude is most evident?', ['Impulsivity','Macho','Resignation','Invulnerability'],0,'Impulsivity is the urge to act immediately without adequate thought.','Human factors','Hazardous attitudes'),
Q('A pilot accepts a demanding approach mainly to prove capability to passengers. Which hazardous attitude is most evident?', ['Resignation','Macho','Anti-authority','Invulnerability'],1,'Macho thinking involves taking unnecessary chances to prove oneself.','Human factors','Hazardous attitudes'),
Q('A pilot encounters a worsening situation and says, “There is nothing I can do now.” Which hazardous attitude is most evident?', ['Resignation','Impulsivity','Anti-authority','Macho'],0,'Resignation is the tendency to believe outcomes are beyond one’s control; the antidote is to recognize that useful action is often possible.','Human factors','Hazardous attitudes'),
Q('A pilot is choosing whether to continue a flight toward deteriorating weather. Which action best demonstrates good risk management rather than risk elimination?', ['Demanding that every hazard be removed before any flight','Reducing the likelihood or severity of hazards to an acceptable level while preserving alternatives','Ignoring hazards that cannot be eliminated','Continuing whenever regulations permit'],1,'Aviation always contains some risk. Risk management identifies hazards and reduces their probability or severity to an acceptable level.','Risk management','Risk concepts'),
Q('A pilot discovers the destination runway is unexpectedly closed after departure. In the DECIDE model, recognizing that change is which step?', ['Detect','Estimate','Choose','Evaluate'],0,'DECIDE begins by detecting that a change has occurred.','ADM models','DECIDE'),
Q('In the DECIDE model, after detecting a change, what should the pilot do before selecting a course of action?', ['Estimate the need to react and identify the desired outcome before choosing among actions','Immediately execute the first idea','Ignore the change unless ATC issues instructions','Delegate the decision to passengers'],0,'DECIDE requires understanding the significance of the change and the desired result before choosing and implementing an action.','ADM models','DECIDE'),
Q('A pilot diverts to an alternate because weather is deteriorating, then continues monitoring the new route and fuel state. Which ADM principle does that illustrate?', ['A decision ends the risk-management process','Risk management is continuous and the outcome of a decision must be reevaluated','Only preflight decisions require evaluation','Once a diversion is selected, new hazards are irrelevant'],1,'Conditions continue to change. Good ADM includes evaluating whether the chosen action is working and reassessing new hazards.','ADM','Continuous evaluation'),
Q('A passenger repeatedly pressures the pilot to continue because of hotel reservations. Under the 5P model, this pressure belongs most directly to which “P”?', ['Plane','Pilot','Passengers','Programming'],2,'Passengers can create operational pressure and are specifically considered in the 5P check.','Single-pilot resource management','5P model'),
Q('A pilot is flying a technically advanced aircraft but is unfamiliar with the avionics menu structure. Which conclusion best reflects SRM?', ['Advanced avionics always lower risk regardless of pilot familiarity','Unfamiliar automation can add workload and should lead to more conservative planning and earlier programming','The pilot should learn the system while in busy terminal airspace','Hand flying is prohibited when advanced avionics are installed'],1,'Technology can reduce workload when understood, but unfamiliar automation can create distraction, fixation, and error.','Single-pilot resource management','Automation'),
Q('A pilot has several safe alternatives but feels embarrassed about turning back. Which type of risk factor is most directly influencing the decision?', ['External pressure','Aircraft performance','Navigation geometry','Static-system error'],0,'Pride, schedule pressure, passenger expectations, and perceived social consequences are external pressures that can distort decisions.','Risk management','External pressures'),
Q('A pilot completes a written risk-assessment worksheet before departure but never revisits it in flight. What is missing?', ['Nothing; risk assessment is only a preflight task','Ongoing reassessment as conditions, pilot state, aircraft status, and plan change','A second copy of the worksheet','A passenger signature'],1,'Risk management must continue during flight because the risk picture changes.','Risk management','Dynamic risk assessment'),
Q('A pilot is uncertain about a maintenance discrepancy and calls a mechanic or chief flight instructor before deciding. Under TEAM, which strategy is represented?', ['Transfer','Eliminate','Accept','Mitigate'],0,'Transferring a risk decision means involving a person with appropriate expertise or authority when that improves the decision.','Risk management','TEAM checklist'),
Q('Why is “legal” not the same as “safe” in aeronautical decision-making?', ['Regulations define minimum requirements, while actual risk also depends on pilot proficiency, aircraft condition, weather, terrain, and other circumstances','The FAA expects pilots to ignore regulations when conditions are difficult','Safety is determined only by accident statistics','A legal flight always has zero operational risk'],0,'Regulatory compliance is essential but does not account for every combination of operational risk; personal minimums and conservative decisions may need to be more restrictive.','ADM','Legal versus safe'),
Q('A pilot sets personal weather minimums while calm and on the ground. Why can this improve decisions later?', ['It reduces the chance that in-flight pressure or changing emotions will move the pilot toward an unsafe threshold','It guarantees the weather forecast will be correct','It replaces all regulatory weather minimums','It prevents any need to divert'],0,'Pre-established personal minimums create decision boundaries before schedule pressure, fatigue, or commitment bias becomes strong.','Risk management','Personal minimums'),
Q('A pilot realizes fuel is lower than planned but still adequate to reach several nearby airports. Which decision best preserves options?', ['Continue toward the most distant destination until fuel becomes critical','Divert early to a suitable airport while choices remain plentiful','Wait until the fuel warning system activates','Ignore the discrepancy because the original plan was legal'],1,'Early action preserves time, fuel, airports, and weather alternatives. Waiting usually narrows options and raises risk.','ADM','Option preservation'),
Q('A pilot becomes fixated on troubleshooting a minor avionics problem while altitude and heading begin to wander. What resource-management principle has been violated?', ['Prioritize aircraft control and situational awareness before lower-priority troubleshooting','Resolve every equipment problem before touching the flight controls','Automation should be allowed to manage all flight-path deviations','Only ATC is responsible for aircraft separation'],0,'Aviate, navigate, communicate reflects workload prioritization: maintain control and awareness before troubleshooting noncritical systems.','Single-pilot resource management','Workload management'),
Q('A pilot receives advice from ATC that would place the airplane into weather the pilot considers unsafe. What ADM principle applies?', ['ATC removes PIC responsibility once a clearance is issued','The PIC remains responsible for the safe operation and should communicate inability or request an alternative','The pilot must comply even if the operation is unsafe','Passengers should decide whether to accept the risk'],1,'External resources support decisions, but the PIC retains responsibility and should decline or amend a plan that cannot be conducted safely.','ADM','PIC responsibility'),
Q('A pilot has a strong desire to complete a trip but deliberately lists reasons to cancel, divert, or delay. What decision-making benefit does this provide?', ['It counters confirmation bias by forcing consideration of evidence against the preferred plan','It guarantees the conservative choice is always correct','It eliminates the need for weather data','It transfers PIC authority to a checklist'],0,'Actively seeking disconfirming evidence helps prevent a pilot from interpreting information only in ways that support the desired outcome.','Human factors','Confirmation bias'),
Q('A pilot has completed a flight safely after accepting a questionable risk. What is the best lesson?', ['The decision was proven safe because no accident occurred','A favorable outcome does not validate the quality of the decision; the risk process should be reviewed independently of luck','The same risk should be accepted next time','Personal minimums should be relaxed after every successful flight'],1,'Outcome bias can make unsafe decisions seem acceptable when nothing bad happens. Good ADM evaluates the process and available information, not just the result.','Human factors','Outcome bias'),
Q('Which statement best describes expert aeronautical decision-making?', ['It means never making mistakes','It is a disciplined process of recognizing hazards, evaluating risk, choosing and implementing controls, and continuously reassessing as conditions change','It depends primarily on instinct developed after many hours','It requires always choosing the most conservative possible option regardless of context'],1,'Good ADM is systematic and continuous. Experience helps, but disciplined risk-management processes remain essential.','ADM','ADM process')
]

chapters[3]=[
Q('During a preflight inspection, a pilot finds a pronounced wrinkle in stressed fuselage skin near a structural attachment point. Why should this be treated seriously?', ['In semimonocoque construction, skin and internal members share structural loads, so deformation can indicate compromised load paths','Fuselage skin is only cosmetic and never carries load','Wrinkles improve flexibility under turbulence','Only wing skin contributes to aircraft strength'],0,'In semimonocoque structures, stressed skin works with frames, bulkheads, and stringers to carry loads. Distortion can indicate structural damage.','Airframe structure','Semimonocoque construction'),
Q('A wing inspection reveals damage to a primary spanwise structural member. Which component is most likely involved?', ['Rib','Spar','Fairing','Cowling'],1,'Wing spars are principal spanwise load-carrying members.','Wing structure','Wing spars'),
Q('Why are wing ribs important even though the spars carry major bending loads?', ['They establish the airfoil shape and transfer/distribute loads between skin and spars','They provide engine ignition','They control yaw','They store hydraulic pressure'],0,'Ribs help maintain airfoil geometry and distribute loads into the wing structure.','Wing structure','Wing ribs'),
Q('A pilot loads baggage far behind the cabin. From a structural perspective, why must the pilot respect baggage-area limitations in addition to total aircraft weight?', ['Local structure has design load limits, so a legal total weight can still overload a specific compartment or attachment area','Any load is acceptable if total weight is below maximum','Only the landing gear has localized structural limits','Baggage location affects comfort but not structure'],0,'Aircraft structures are designed for both total loads and local load distributions. Compartment and floor limits protect local structure.','Structural loads','Load distribution'),
Q('An airplane experiences a strong upward gust. Which structural stress is the wing spar primarily designed to resist as lift bends the wings upward?', ['Bending','Pure compression only','Electrical arcing','Magnetic variation'],0,'Lift loads create significant bending moments in the wing structure.','Structural loads','Bending'),
Q('A control cable is pulled from both ends during operation. Which basic structural stress is acting in the cable?', ['Compression','Tension','Torsion','Bending only'],1,'A cable carrying a pulling load is primarily in tension.','Structural loads','Tension'),
Q('A tubular landing-gear member is twisted about its long axis during an abnormal side load. Which stress best describes that loading?', ['Torsion','Tension only','Shear only','Camber'],0,'Twisting about a member’s longitudinal axis is torsion.','Structural loads','Torsion'),
Q('Two joined structural parts tend to slide past each other along their attachment plane. Which stress is most relevant?', ['Shear','Compression only','Bending only','Lift'],0,'Shear acts when adjacent material tends to slide in opposite directions along a plane.','Structural loads','Shear'),
Q('Why is corrosion on an aluminum airframe more than a cosmetic concern?', ['It can remove material and reduce the cross-sectional strength of structural members','It only changes paint adhesion','It increases useful load','It automatically strengthens stressed skin'],0,'Corrosion can reduce material thickness and strength, compromising the structure.','Materials','Corrosion'),
Q('A composite surface is struck during ground handling but shows little external damage. Why may further inspection still be necessary?', ['Composite structures can sustain hidden internal damage such as delamination','Composite materials cannot be damaged by impact','Visible damage is required before structural strength changes','Only aluminum requires impact inspection'],0,'Composite damage can be internal and difficult to see, so impact events may require inspection beyond the surface appearance.','Materials','Composite damage'),
Q('A pilot compares monocoque and semimonocoque fuselages. What is the key structural difference?', ['Monocoque relies primarily on the stressed skin for loads; semimonocoque supplements stressed skin with internal members','Semimonocoque has no stressed skin','Monocoque uses only cables','They differ only in cabin shape'],0,'Monocoque construction depends mainly on the shell; semimonocoque combines stressed skin with frames, bulkheads, and stringers.','Airframe structure','Monocoque vs semimonocoque'),
Q('A pilot sees a cracked wing fairing. Why should the pilot not assume it is harmless just because a fairing is generally non-primary structure?', ['The damage must still be evaluated because it may indicate impact, loose parts, or adjacent structural damage','Fairings are always primary spars','Any crack automatically grounds every airplane permanently','Fairings determine magnetic heading'],0,'Even non-primary components can create hazards or reveal underlying damage; airworthiness should be determined using proper maintenance procedures.','Airworthiness','Damage assessment'),
Q('What is the primary aerodynamic/structural function of the horizontal stabilizer on a conventional tail airplane?', ['Contribute to longitudinal stability and provide the surface associated with pitch control','Provide directional stability about the vertical axis','Produce all engine thrust','Support the main landing gear'],0,'The horizontal tail contributes to pitch stability about the lateral axis and carries the elevator or may itself move as a stabilator.','Empennage','Horizontal stabilizer'),
Q('What is the primary function of the vertical stabilizer?', ['Directional stability in yaw','Longitudinal stability in pitch','Roll control','Fuel storage'],0,'The vertical stabilizer provides directional stability about the vertical axis.','Empennage','Vertical stabilizer'),
Q('A pilot notices play in a flight-control hinge during preflight. Why is this significant?', ['Excessive looseness can alter control-surface movement and may indicate worn or damaged attachment hardware','Hinge play improves control sensitivity','The hinges do not carry aerodynamic loads','Only electrical trim systems use hinges'],0,'Control-surface hinges and attachments transmit aerodynamic loads and must operate within approved condition and limits.','Control surfaces','Hinges and attachments'),
Q('Why does a tricycle landing-gear airplane generally resist ground looping better than a tailwheel airplane?', ['The center-of-gravity/gear geometry tends to provide more stable ground handling with the main gear behind the CG','The nosewheel produces aerodynamic lift','Tricycle gear eliminates all crosswind effects','Tailwheel airplanes have no brakes'],0,'With tricycle gear, the CG is generally ahead of the main gear, which tends to resist rather than amplify a yaw on the ground.','Landing gear','Tricycle gear stability'),
Q('A tailwheel airplane begins yawing during rollout. Why can the yaw grow rapidly if not corrected?', ['Its CG is behind the main gear, so inertia can amplify the turn into a ground loop','The tailwheel always locks at high speed','The vertical stabilizer stops producing any force after touchdown','The engine automatically adds asymmetric thrust'],0,'The CG-aft-of-main-gear geometry of conventional gear can make ground directional deviations dynamically unstable.','Landing gear','Tailwheel characteristics'),
Q('Why are aluminum alloys widely used in many light-aircraft structures?', ['They provide a useful combination of strength, low weight, workability, and corrosion resistance when properly protected','They are heavier than steel and therefore reduce gust loads','They cannot fatigue','They are unaffected by corrosion'],0,'Aluminum alloys offer favorable strength-to-weight and manufacturing characteristics, though they still require corrosion and fatigue control.','Materials','Aluminum alloys'),
Q('Why are composite materials attractive for aircraft structures?', ['They can provide high strength-to-weight ratios and be formed into efficient complex shapes','They eliminate the need for inspection','They are immune to heat and impact damage','They conduct electricity exactly like aluminum'],0,'Composites can be light and strong and allow efficient shapes, but have their own inspection and damage concerns.','Materials','Composites'),
Q('A mechanic explains that a bulkhead is damaged. What is the likely structural role of that component?', ['A transverse fuselage member that helps maintain shape and carry/distribute loads','A spanwise wing member only','A movable yaw-control surface','A fuel-metering device'],0,'Bulkheads are transverse fuselage structural members that help shape and strengthen the fuselage and carry concentrated loads.','Airframe structure','Bulkheads'),
Q('What is the function of stringers or longerons in a semimonocoque fuselage?', ['Provide longitudinal reinforcement and help carry/distribute loads','Act as primary navigation antennas','Control flap deflection','Vent the fuel tanks'],0,'Longitudinal structural members reinforce the skin and frames and contribute to carrying fuselage loads.','Airframe structure','Longitudinal members'),
Q('During turbulence, why is it important to remain within aircraft speed and load limitations even if no visible damage occurs?', ['Structural loads can exceed design limits before damage becomes obvious','The airframe has unlimited strength below redline airspeed','Only landing loads can damage structure','Turbulence affects passengers but not structural loading'],0,'Aircraft certification establishes structural load limits. Excessive aerodynamic loads can cause permanent deformation or failure.','Structural loads','Load limits'),
Q('A pilot finds a missing inspection-panel fastener before flight. Why can a seemingly small fastener matter?', ['Fasteners can be part of a load path or prevent panels from opening into the airflow; the discrepancy requires proper evaluation','Fasteners are decorative only','A missing fastener increases lift','Only rivets in the wingtip matter'],0,'Fasteners secure components and may transfer load. Missing hardware can affect structural integrity or create an aerodynamic hazard.','Airworthiness','Fasteners'),
Q('Which description best distinguishes a fuselage frame from a wing rib?', ['A frame is primarily a transverse fuselage member; a rib primarily gives a wing its airfoil cross-section','Both terms always mean the same part','A frame controls pitch while a rib controls yaw','Ribs are found only in landing gear'],0,'Frames and bulkheads shape/support fuselages; ribs shape and support wings and other airfoils.','Airframe structure','Frames and ribs'),
Q('Why does an aircraft manufacturer specify approved repair methods rather than allowing any strong-looking patch?', ['Aircraft repairs must restore the intended load path, stiffness, aerodynamic contour, and material compatibility','Any patch is acceptable if it adds weight','Repairs affect appearance only','A stronger patch can never change load distribution'],0,'A repair must fit the original structural design; excessive stiffness, poor load transfer, or incompatible materials can create new failure points.','Airworthiness','Structural repairs'),
Q('A pilot sees oil-canning or unusual skin movement during a walkaround. What is the best response?', ['Treat it as a possible structural discrepancy and have it evaluated rather than assuming it is normal','Press the skin flat and depart','Ignore any deformation outside the cockpit','Increase tire pressure to compensate'],0,'Unexpected skin deformation can indicate damage, loosened structure, or buckling and deserves proper inspection.','Airworthiness','Preflight structural inspection'),
Q('Why are control surfaces often mass-balanced?', ['To reduce the tendency for destructive aerodynamic flutter','To increase static-system pressure','To move the CG outside limits','To increase parasite drag intentionally'],0,'Mass balancing helps prevent control-surface flutter by controlling inertial characteristics around the hinge line.','Control surfaces','Flutter prevention'),
Q('A pilot adds an unapproved external accessory to the airframe. Why can this affect more than appearance?', ['It may alter drag, loads, vibration, weight and balance, and approved configuration','External additions cannot affect certified performance','Only engine modifications require approval','Any accessory is acceptable below maneuvering speed'],0,'Changes to the aircraft configuration can affect structural and aerodynamic characteristics and must follow approved data and procedures.','Airworthiness','Alterations'),
Q('A pilot asks why knowing basic structure matters if maintenance is performed by mechanics. What is the best answer?', ['Pilots must recognize discrepancies during preflight and understand how loading and operation can stress the airframe','Pilots are expected to make structural repairs in flight','Structural knowledge replaces maintenance inspections','Structure matters only to aerobatic pilots'],0,'Pilots are responsible for determining whether the aircraft is in condition for safe flight and need enough structural knowledge to identify and respond to discrepancies.','Airworthiness','Pilot structural awareness'),
Q('What is the most useful operational takeaway from aircraft-construction knowledge?', ['Understand the major load paths and components well enough to avoid improper loading, recognize damage, and respect limitations','Memorize material brand names','Assume any damage is safe if flight controls move','Use structure knowledge only for written tests'],0,'Structural knowledge supports safe preflight inspection, loading, operation, and communication with maintenance personnel.','Airworthiness','Operational application')
]

chapters[4]=[
Q('An airplane climbs to a higher altitude without other changes. Why does the wing generally need either more true airspeed or a higher lift coefficient to produce the same lift?', ['Air density decreases with altitude, reducing dynamic pressure at a given true airspeed','Gravity disappears with altitude','The chord line becomes shorter','The wing loses camber permanently'],0,'Lift depends on air density, velocity, wing area, and lift coefficient. Lower density reduces dynamic pressure for the same true airspeed.','Atmosphere','Density and lift'),
Q('A pilot flies from cool dense air into hot high-altitude conditions. What aerodynamic/engine consequence should be anticipated?', ['Lower air density reduces wing, propeller, and engine performance','Higher density improves takeoff acceleration','Humidity has no effect on density','Pressure increases with altitude'],0,'Hot, high conditions reduce density, which degrades aerodynamic and powerplant performance.','Atmosphere','Air density'),
Q('Why does a wing surface roughened by frost or contamination create concern even before a stall occurs?', ['Surface roughness can disturb the boundary layer, increase drag, and reduce the wing’s ability to produce lift efficiently','Roughness always lowers stall speed','Only the lower wing surface matters','Boundary-layer behavior is unrelated to airfoil performance'],0,'The boundary layer is sensitive to surface condition. Contamination can cause earlier separation and degrade lift/drag performance.','Fluid behavior','Boundary layer'),
Q('As airflow passes through the throat of a venturi and speeds up, what generally happens to static pressure?', ['It decreases','It increases in direct proportion','It remains fixed regardless of velocity','It becomes equal to dynamic pressure'],0,'Bernoulli’s principle describes an inverse relationship between flow speed and static pressure along a streamline under the applicable assumptions.','Pressure and velocity','Bernoulli principle'),
Q('A wing produces lift while deflecting airflow downward. Which principle helps explain the reaction force on the wing?', ['Newton’s third law','Ohm’s law','Archimedes’ principle alone','Magnetic variation'],0,'Changing the momentum of airflow downward produces an equal and opposite reaction on the wing.','Lift theory','Newton laws'),
Q('A pilot raises the nose but the flight path initially continues nearly level. What happens to angle of attack?', ['It increases because the chord line rotates relative to the oncoming relative wind','It must decrease because pitch increased','It is determined only by airspeed','It becomes zero whenever the flight path is level'],0,'Angle of attack is the angle between the chord line and relative wind, not simply pitch attitude relative to the horizon.','Airfoil geometry','Angle of attack'),
Q('An airplane is descending on a steady glide path with the nose slightly above the horizon. Which statement about relative wind is correct?', ['Relative wind is opposite the flight path, so it approaches the wing from below the geometric horizon line','Relative wind is always horizontal','Relative wind is opposite the airplane’s pitch attitude','Relative wind always comes from directly ahead along the fuselage axis'],0,'Relative wind is parallel and opposite to the airfoil’s flight path through the air. Pitch attitude and flight path are not necessarily the same.','Airfoil geometry','Relative wind'),
Q('Why can a symmetrical airfoil produce lift even though its upper and lower surfaces have equal geometric curvature?', ['A positive angle of attack changes the airflow and pressure/momentum distribution to create lift','Symmetrical airfoils can produce lift only when inverted','Camber is the only possible source of lift','The wing must be moving vertically'],0,'Lift is not dependent on camber alone; angle of attack and airflow deflection/pressure distribution allow symmetrical airfoils to generate lift.','Airfoil design','Symmetrical airfoils'),
Q('A wing’s chord line is used primarily as what reference?', ['A straight geometric line from leading edge to trailing edge for defining airfoil geometry and angle of attack','The actual path followed by every air molecule','A line that always points toward the horizon','The centerline of the fuselage'],0,'The chord line is a geometric reference connecting the leading and trailing edges.','Airfoil geometry','Chord line'),
Q('If true airspeed doubles while density and configuration remain constant, how does dynamic pressure change?', ['It becomes four times as large','It doubles','It halves','It remains unchanged'],0,'Dynamic pressure varies with the square of velocity, so doubling speed produces four times the dynamic pressure.','Pressure and velocity','Dynamic pressure','advanced','calculation'),
Q('Why does air pressure decrease with increasing altitude in the atmosphere?', ['There is less weight of air above the point exerting pressure','Oxygen turns into nitrogen','Gravity reverses above sea level','Air molecules become heavier'],0,'Atmospheric pressure is produced by the weight of the air column above; that column becomes smaller with altitude.','Atmosphere','Pressure with altitude'),
Q('A pilot hears “standard atmosphere” used in performance calculations. Why is that concept useful?', ['It provides a reference set of pressure, temperature, and density conditions from which nonstandard performance effects can be evaluated','It describes the actual weather at every airport','It eliminates the need for aircraft performance charts','It guarantees sea-level density at all temperatures'],0,'Standard atmosphere is a reference model used to compare actual conditions and calculate performance-related quantities.','Atmosphere','Standard atmosphere'),
Q('At the same pressure altitude, which condition produces the lowest air density?', ['High temperature and high humidity','Low temperature and dry air','Low temperature and high pressure','Cold dry winter air'],0,'Higher temperature lowers density, and water vapor is less dense than dry air, so humidity also reduces density slightly.','Atmosphere','Density factors'),
Q('Why can high humidity slightly degrade aircraft performance?', ['Replacing some dry-air molecules with lighter water-vapor molecules reduces air density','Water vapor makes the air heavier','Humidity raises oxygen percentage','Humidity increases propeller blade area'],0,'Humid air is slightly less dense than dry air at the same pressure and temperature.','Atmosphere','Humidity and density'),
Q('A pilot increases wing angle of attack while remaining below the critical angle. What is the general aerodynamic effect?', ['Lift coefficient generally increases, along with induced-drag effects','Lift coefficient must immediately fall to zero','Relative wind changes to align with the chord','Air density doubles'],0,'Below the critical angle, increasing angle of attack generally increases lift coefficient, while drag also changes.','Airfoil behavior','Angle of attack and lift'),
Q('What is the most important reason not to think of Bernoulli and Newton as competing explanations of lift?', ['Both describe aspects of the same airflow physics: pressure distribution and momentum change are consistent parts of the force on the wing','Only one can be true at a time','Bernoulli applies only to liquids','Newton’s laws do not apply to air'],0,'Lift involves pressure forces and changes in airflow momentum; Bernoulli and Newtonian descriptions are complementary.','Lift theory','Integrated lift explanation'),
Q('A pilot increases airspeed while holding lift constant in level flight. What generally must happen to lift coefficient?', ['It must decrease because higher dynamic pressure can produce the same lift with a lower coefficient','It must increase in exact proportion to speed','It remains fixed for every speed','It becomes negative'],0,'For constant lift, increasing dynamic pressure requires a lower lift coefficient, normally achieved with lower angle of attack.','Pressure and velocity','Lift equation reasoning'),
Q('A pilot slows in level flight while maintaining altitude. What general change is required before reaching the critical angle?', ['Increase angle of attack to maintain the required lift as dynamic pressure decreases','Decrease angle of attack continuously to zero','Reduce lift to less than weight','Move the CG aft automatically'],0,'As speed decreases, the pilot must generally increase lift coefficient/angle of attack to maintain lift equal to weight.','Airfoil behavior','Slow-flight lift'),
Q('Why is the center of pressure operationally important?', ['Its position represents where the resultant aerodynamic lift force acts and can shift with angle of attack, affecting pitching moments','It is the same as the aircraft center of gravity in all conditions','It determines fuel octane','It is fixed at the leading edge'],0,'Movement of the resultant aerodynamic force location changes pitching moments and interacts with stability and control.','Airfoil behavior','Center of pressure'),
Q('Which statement about viscosity and the boundary layer is most accurate?', ['Air viscosity causes air near the surface to slow, creating a boundary layer in which velocity changes from near zero at the surface to free-stream value','Air has zero viscosity, so no boundary layer forms','The boundary layer exists only during stalls','Boundary-layer air always moves faster than the free stream'],0,'Viscosity and friction make the fluid adhere to the surface and create a velocity gradient through the boundary layer.','Fluid behavior','Viscosity and boundary layer'),
Q('Why is a smooth, clean leading edge important?', ['It helps maintain the intended boundary-layer and pressure behavior; contamination can trigger premature separation','It increases aircraft mass for stability','It eliminates induced drag','It changes magnetic variation'],0,'Leading-edge condition strongly influences airflow attachment and the wing’s ability to generate lift.','Fluid behavior','Surface condition'),
Q('A pilot observes that indicated airspeed for a given aerodynamic condition changes much less with altitude than true airspeed. Which idea explains this?', ['Indicated airspeed is related to dynamic pressure sensed by the pitot-static system, while true airspeed accounts for actual air density','Indicated airspeed measures GPS groundspeed','True airspeed is independent of density','Both instruments always show identical values'],0,'The wing responds to dynamic pressure; indicated airspeed approximates that pressure effect, while true airspeed increases as density decreases for a given dynamic pressure.','Pressure and velocity','IAS versus TAS concept'),
Q('What is the operational value of understanding that air is a fluid?', ['It allows pilots to reason about pressure, velocity, viscosity, boundary layers, and forces on airfoils','It means air behaves exactly like water in every situation','It eliminates compressibility effects','It proves drag can be ignored'],0,'Treating air as a fluid provides the physical framework for understanding aerodynamic flow and forces.','Fluid behavior','Air as a fluid'),
Q('An airplane accelerates while thrust exceeds drag. Which Newtonian idea is most directly illustrated?', ['A net force produces acceleration','Every moving body must slow automatically','Pressure is unrelated to velocity','Mass disappears when airborne'],0,'Under Newton’s second law, a net force causes acceleration proportional to that force and inversely proportional to mass.','Lift theory','Newton second law'),
Q('A propeller accelerates a mass of air rearward. Which reaction contributes to thrust?', ['The air exerts an equal and opposite forward force on the propeller','The rearward airflow pulls the airplane backward','Only static pressure ahead of the propeller creates thrust','No reaction occurs because air is compressible'],0,'Newton’s third law applies: accelerating air rearward produces a forward reaction on the propeller/aircraft.','Lift theory','Newton third law'),
Q('Why is angle of attack a more fundamental aerodynamic variable than pitch attitude for stall awareness?', ['A stall occurs when the wing exceeds critical angle of attack, which can happen at many pitch attitudes and airspeeds','A stall occurs only when the nose is above the horizon','Pitch attitude directly measures airflow separation','Angle of attack has no relation to lift'],0,'The wing stalls based on its angle to the relative wind, not its visual pitch attitude.','Airfoil behavior','AOA significance'),
Q('A pilot enters a rising airmass that changes the flight path faster than the airplane’s attitude changes. Can angle of attack change without a control input?', ['Yes; a change in relative-wind direction can change angle of attack even if pitch attitude initially stays the same','No; angle of attack changes only when the elevator moves','No; angle of attack is fixed by wing construction','Only if the engine fails'],0,'Angle of attack depends on the relationship between chord and relative wind, so gusts can change it even before the aircraft attitude changes.','Airfoil behavior','Gust effects on AOA'),
Q('Why does a high-elevation, hot-day takeoff require special attention even though indicated liftoff speed may be similar to a low-elevation takeoff?', ['The airplane needs a higher true airspeed and groundspeed to achieve the same dynamic pressure, while power and propeller performance are also reduced','The airplane lifts off at a lower true airspeed because density is lower','Runway length becomes irrelevant','Lift coefficient doubles automatically'],0,'At lower density, the indicated aerodynamic speed may be similar but true airspeed/groundspeed are higher and powerplant/propeller performance is poorer.','Atmosphere','High-density-altitude reasoning'),
Q('What should a pilot be able to articulate after studying basic flight principles?', ['How density, velocity, angle of attack, pressure distribution, and airflow momentum combine to create aerodynamic forces','Only the names of early scientists','That lift has one single cause independent of airflow','That aircraft performance is unrelated to atmosphere'],0,'The practical value is the ability to connect atmospheric conditions and wing geometry to the aerodynamic forces the pilot controls.','Lift theory','Operational synthesis'),
Q('A pilot says “the wing needs air moving over it, so a strong headwind on the ramp should make the airplane fly even with zero airspeed relative to the airmass.” What concept corrects this?', ['Aerodynamic forces depend on the wing’s motion relative to the surrounding air; a stationary airplane in a uniform wind does have airspeed relative to the airmass, but whether it can lift off also depends on restraints, orientation, lift, and weight—not groundspeed alone','Only groundspeed creates lift','Wind cannot create relative airflow over a stationary wing','Airspeed and groundspeed are always identical'],0,'Aerodynamics respond to relative airflow, not groundspeed. A stationary aircraft in wind has airspeed relative to the air, though actual liftoff depends on the complete force and constraint situation.','Airfoil behavior','Airspeed versus groundspeed','advanced')
]

chapters[5]=[
Q('An airplane is in straight-and-level, unaccelerated flight at constant speed. What force relationship must exist?', ['Lift equals weight and thrust equals drag','Lift exceeds weight and thrust exceeds drag','Weight equals drag and lift equals thrust','Thrust equals weight only'],0,'With no vertical or longitudinal acceleration, the opposing force components are balanced: lift equals weight and thrust equals drag.','Four forces','Force balance'),
Q('A pilot begins a steady climb at constant airspeed. Why is it inaccurate to say that lift must simply be greater than weight for the entire climb?', ['In a steady climb the force vectors are tilted relative to the flight path; a component of weight acts along the path, so force balance is not the same as level flight','Lift disappears in a climb','Weight becomes zero above the ground','Thrust always equals weight exactly'],0,'In a steady climb, forces resolve along and perpendicular to the flight path; the vector relationships differ from level flight.','Four forces','Climb force vectors'),
Q('During a power-off glide at constant airspeed, what provides the forward component that balances drag?', ['A component of the airplane’s weight acting along the descending flight path','Residual propeller thrust only','Lift tilted forward by the elevator','Static pressure from the pitot tube'],0,'In a glide, part of the weight vector acts along the flight path and supplies the force that balances drag.','Four forces','Glide force vectors'),
Q('A pilot slows while maintaining level flight. What combination is generally required as speed decreases?', ['Increase angle of attack to maintain lift, which also increases induced drag','Decrease angle of attack and induced drag rises','Keep angle of attack fixed and lift remains constant automatically','Reduce lift below weight while holding altitude'],0,'At lower dynamic pressure, the wing needs a higher lift coefficient/angle of attack to support the same weight, increasing induced drag.','Lift and drag','Slow flight'),
Q('At high speed in level flight, which drag component generally dominates?', ['Parasite drag','Induced drag','Weight drag','Lift-independent vortex drag only at zero speed'],0,'Parasite drag rises rapidly with speed, while induced drag is greatest at low speed/high lift coefficient.','Drag','Parasite drag'),
Q('At very low speed in level flight, which drag component generally becomes large?', ['Induced drag','Skin-friction drag only','Form drag becomes zero','Wave drag in every light airplane'],0,'Producing the required lift at low speed requires high angle of attack and lift coefficient, which increases induced drag.','Drag','Induced drag'),
Q('Why does the total-drag curve have a minimum at an intermediate airspeed?', ['Parasite drag decreases as speed is reduced while induced drag increases, creating a point where their sum is lowest','Both drag components are zero at the same speed','Induced and parasite drag both increase continuously with speed','Weight cancels drag at that point'],0,'The opposing trends of parasite and induced drag produce a minimum total-drag condition near best lift-to-drag ratio.','Drag','Total drag curve'),
Q('A pilot steepens a coordinated level turn from 30° to 60° bank while maintaining altitude. What must happen to lift and load factor?', ['Total lift must increase because only its vertical component supports weight, so load factor rises','Lift decreases because bank angle creates more vertical lift','Load factor remains 1 G in every level turn','Weight decreases with bank angle'],0,'Banking tilts the lift vector. To keep the vertical component equal to weight, total lift must increase, raising load factor.','Turns and load factor','Level turns'),
Q('In a coordinated 60° banked level turn, the load factor is approximately 2 G. What happens to stall speed compared with 1-G flight?', ['It increases by approximately the square root of 2','It is cut in half','It remains exactly the same','It doubles exactly'],0,'Stall speed increases with the square root of load factor, so 2 G raises stall speed by about 41 percent.','Stalls and load factor','Accelerated stall','advanced','calculation'),
Q('Why can an airplane stall at any airspeed and any attitude?', ['A stall is caused by exceeding critical angle of attack, not by a particular airspeed or pitch attitude','Every stall requires zero airspeed','Stalls occur only nose-high','Airspeed alone determines angle of attack'],0,'Critical angle of attack is the direct aerodynamic cause of a stall; high load factor or abrupt control inputs can reach it at higher airspeeds.','Stalls','Critical angle of attack'),
Q('A pilot makes an abrupt pull-up at an airspeed well above the normal 1-G stall speed. What aerodynamic event can occur first?', ['An accelerated stall if the increased load factor drives the wing beyond critical angle of attack','A stall is impossible above the published stall speed','Induced drag becomes zero','Weight disappears during the pull-up'],0,'Higher load factor requires greater lift and angle of attack, which can produce a stall at a higher airspeed.','Stalls and load factor','Accelerated stalls'),
Q('What is the principal reason maneuvering speed decreases as aircraft weight decreases?', ['At a lighter weight, the wing can reach the structural load limit at a lower airspeed relative to the stall/load relationship, so the published maneuvering speed must be lower','A lighter airplane has a higher stall speed','Control surfaces stop working at high speed','Maneuvering speed is independent of weight'],0,'Maneuvering speed is weight dependent; the lighter aircraft reaches the relevant aerodynamic/structural relationship at a lower speed.','Load factor','Maneuvering speed','advanced'),
Q('A pilot encounters a sharp gust. Why does reducing to an appropriate turbulence penetration/maneuvering speed reduce structural risk?', ['It increases the likelihood the wing will stall before excessive aerodynamic load can be imposed by a full abrupt input or gust, within the assumptions of the speed','It makes the wing unable to stall','It eliminates all gust loads','It raises the aircraft structural limit factor'],0,'An appropriate maneuvering/turbulence speed provides greater protection from excessive aerodynamic loads, though it is not immunity from all structural damage or multiple control inputs.','Load factor','Turbulence and maneuvering speed'),
Q('When are wake vortices from a fixed-wing aircraft generally strongest?', ['When the generating aircraft is heavy, clean, and slow','When it is light, dirty, and fast','Only after touchdown','Only when flaps are fully extended'],0,'Strongest vortices occur with high lift demand: heavy weight, clean configuration, and slow speed.','Wake turbulence','Vortex strength'),
Q('A light airplane is landing behind a larger airplane. Which strategy best reduces wake-vortex exposure?', ['Stay at or above the larger airplane’s final approach path and land beyond its touchdown point when practical and safe','Fly below the larger airplane’s glidepath','Aim to touch down before the larger airplane’s touchdown point','Follow directly behind at minimum separation if winds are calm'],0,'Vortices sink and move with the wind; remaining above the generating aircraft’s path and avoiding its touchdown region reduces exposure.','Wake turbulence','Avoidance'),
Q('Why does ground effect reduce induced drag near the surface?', ['The ground interferes with wingtip-vortex/downwash development, reducing induced angle and induced drag','The ground removes parasite drag','Air density doubles near every runway','The wing’s span increases'],0,'Ground proximity alters the wing’s vortex system and downwash, reducing induced drag and changing lift characteristics.','Ground effect','Induced drag in ground effect'),
Q('What risk can occur if a pilot lifts off in ground effect at a high-density-altitude airport before the airplane has enough speed to climb out of ground effect?', ['The airplane may fly in ground effect but be unable to climb once induced drag increases outside it','Ground effect guarantees climb performance','Induced drag decreases further after leaving ground effect','Stall speed becomes zero near the ground'],0,'An airplane can become airborne in ground effect at a speed that is insufficient for an out-of-ground-effect climb, especially when performance is marginal.','Ground effect','Premature liftoff'),
Q('A pilot extends flaps on approach. What is the typical combined aerodynamic effect?', ['Increase lift coefficient and increase drag, allowing a steeper/lower-speed approach within aircraft limitations','Decrease both lift and drag in all positions','Increase stall speed in every configuration','Eliminate induced drag'],0,'Flaps change camber and often area, increasing lift and drag; their exact effects are aircraft/configuration specific.','Lift and drag','Flaps'),
Q('A pilot carries ice contamination on the leading edge. What is the key stall-related danger?', ['The contamination can reduce maximum lift and cause airflow separation at a lower angle of attack and/or higher airspeed than expected','Ice always lowers stall speed','Only parasite drag changes','The stall warning system automatically compensates for all ice'],0,'Contamination changes the airfoil shape and boundary layer, degrading lift and stall characteristics.','Stalls','Contamination'),
Q('Why does an aft center of gravity generally reduce longitudinal stability?', ['The restoring pitching moments are reduced because the CG is closer to the aerodynamic balance point','The vertical stabilizer becomes larger','The wing produces no lift','The rudder reverses direction'],0,'Moving CG aft reduces the stabilizing leverage/moments required to return the airplane toward equilibrium after a pitch disturbance.','Stability','Longitudinal stability'),
Q('Why can an excessively forward CG make stall recovery more difficult even though it generally increases stability?', ['Greater nose-up control force may be required in normal flight and available elevator authority may be reduced for some maneuvers, especially flare; recovery/control margins are aircraft specific','Forward CG always makes the airplane uncontrollable in yaw','Forward CG eliminates tail downforce','Forward CG reduces all control forces'],0,'Forward CG increases stability but can require greater tail force/elevator authority and degrade performance; limits ensure adequate control.','Stability','Forward CG effects'),
Q('What is static stability?', ['The initial tendency of an aircraft to return toward, remain at, or move away from equilibrium after a disturbance','The time required for all oscillations to stop','The structural strength of the landing gear','The ability to maintain constant groundspeed'],0,'Static stability describes the initial response to a displacement. Dynamic stability describes how the motion evolves over time.','Stability','Static stability'),
Q('An airplane initially tends to return toward equilibrium after a disturbance but its oscillations grow with time. How should its stability be described?', ['Positive static stability but negative dynamic stability','Negative static and positive dynamic stability','Neutral static and neutral dynamic stability','Positive dynamic stability only'],0,'The initial restoring tendency is positive static stability, but increasing oscillation amplitude indicates negative dynamic stability.','Stability','Dynamic stability','advanced'),
Q('Why does dihedral contribute to lateral stability?', ['A sideslip changes the effective angle of attack/lift between the wings, tending to roll the airplane back toward level','It directly controls yaw with the rudder','It moves the CG forward','It removes adverse yaw'],0,'Dihedral geometry creates a restoring roll tendency during sideslip.','Stability','Dihedral effect'),
Q('What is the primary role of the vertical tail in directional stability?', ['Provide a weather-vane tendency that aligns the airplane with the relative wind after a yaw disturbance','Control pitch about the lateral axis','Increase induced drag in turns','Measure magnetic heading'],0,'The vertical stabilizer produces a restoring yawing moment when the aircraft is sideslipped.','Stability','Directional stability'),
Q('A pilot enters a coordinated level turn and then increases bank without increasing back pressure. What is the likely immediate flight-path tendency?', ['The airplane will begin descending because the vertical component of lift is reduced','The airplane climbs because horizontal lift becomes vertical','Airspeed must instantly become zero','Load factor decreases below 1 G automatically'],0,'Banking tilts lift. Without increasing total lift, the vertical component becomes less than weight, causing a descent.','Turns and load factor','Vertical lift component'),
Q('Why does turn radius increase with true airspeed at a given bank angle?', ['More distance is traveled while the same bank produces a given rate of change in direction; mathematically radius rises with the square of speed for fixed bank','Higher speed always increases bank angle automatically','Lift no longer acts in a turn','Turn radius depends only on aircraft weight'],0,'For a coordinated level turn at fixed bank, radius increases strongly with speed.','Turns and load factor','Turn radius'),
Q('At a given true airspeed, what happens to rate of turn as bank angle increases in a coordinated level turn?', ['Rate of turn increases','Rate of turn decreases','Rate of turn is independent of bank','Rate of turn becomes zero above 30°'],0,'A steeper bank creates a larger horizontal lift component and higher centripetal acceleration, increasing turn rate at a given speed.','Turns and load factor','Rate of turn'),
Q('A pilot wants the best glide distance in still air. Which aerodynamic condition is fundamentally being sought?', ['Maximum lift-to-drag ratio','Maximum induced drag','Maximum angle of attack below stall regardless of speed','Minimum true airspeed'],0,'Best glide distance in still air is associated with the airplane’s maximum lift-to-drag ratio, subject to aircraft-specific guidance.','Lift and drag','Best L/D'),
Q('What should a student ultimately be able to explain about airplane control from aerodynamics alone?', ['How changing power, attitude, angle of attack, configuration, and bank changes the balance of lift, weight, thrust, drag, load factor, and stall margin','Only the memorized names of the four forces','That stall speed never changes','That lift always acts vertically upward'],0,'Operational understanding requires connecting pilot inputs and configuration to changing force vectors, drag, load factor, and stall behavior.','Aerodynamics','Operational synthesis')
]

chapters[6]=[
Q('A pilot rolls right with conventional ailerons. What coordinated control input is normally required to counter adverse yaw?', ['Right rudder as needed','Left rudder only','Forward elevator','Flaps down'],0,'The down-going aileron on the rising wing generally creates more drag, tending to yaw opposite the roll. Coordinated rudder counters that adverse yaw.','Primary controls','Ailerons and adverse yaw'),
Q('A pilot moves the control wheel left. Which initial control-surface response should occur in a conventional aileron system?', ['Left aileron rises and right aileron lowers','Both ailerons rise','Left aileron lowers and right aileron rises','Both ailerons lower'],0,'Raising the left aileron reduces lift on the left wing while lowering the right increases lift on the right, producing a left roll.','Primary controls','Aileron operation'),
Q('A pilot pulls aft on the yoke of a conventional-tail airplane. What control-surface action normally initiates the pitch-up?', ['Elevator trailing edge moves up, increasing downward force on the tail','Rudder moves left','Ailerons both move down','Elevator trailing edge moves down to push the tail down'],0,'Up elevator changes tail force so the tail moves down and the nose pitches up about the lateral axis.','Primary controls','Elevator operation'),
Q('A pilot presses the right rudder pedal. What is the primary aircraft response?', ['Yaw to the right about the vertical axis','Roll left about the longitudinal axis only','Pitch down about the lateral axis','Increase lift equally on both wings'],0,'Rudder deflection changes side force on the vertical tail and controls yaw about the vertical axis.','Primary controls','Rudder operation'),
Q('Why should a pilot think of pitch, roll, and yaw as coupled rather than independent?', ['A control input can create secondary aerodynamic effects, so coordinated flight often requires more than one control','Each axis is controlled by only one force with no side effects','The controls are mechanically locked together in all airplanes','Coupling occurs only in helicopters'],0,'Aileron drag, propeller effects, sideslip, and changing lift vectors couple the axes; pilots coordinate inputs to achieve the intended flight path.','Control coordination','Coupled axes'),
Q('A pilot holds steady aft pressure in a climb. What is the proper use of trim?', ['Adjust trim to relieve the sustained control force after establishing the desired attitude and airspeed','Use trim to make the airplane change pitch before using the elevator','Use trim as an emergency substitute for all pitch control','Set trim once before takeoff and never change it'],0,'Trim relieves sustained control pressure after the pilot establishes the desired flight condition with the primary controls.','Trim systems','Proper trim use'),
Q('The pilot changes power and airspeed after trimming. Why may retrimming be necessary?', ['Aerodynamic forces on the control surfaces change with speed, power, and configuration','Trim position automatically controls altitude regardless of power','Trim only works on the ground','Changes in power cannot affect pitch forces'],0,'A new flight condition changes control forces and often requires a new trim setting to relieve pressure.','Trim systems','Retrimming'),
Q('What is the key operational danger of trying to fly the airplane with trim instead of the primary flight controls?', ['Trim responds indirectly and can create large out-of-trim forces; primary controls should establish attitude while trim relieves pressure','Trim is always faster than the elevator','Trim has no aerodynamic effect','Using the elevator is prohibited after trimming'],0,'Trim is a workload-reduction device, not the normal primary means of maneuvering.','Trim systems','Trim limitations'),
Q('A stabilator differs from a conventional elevator because what moves?', ['The entire horizontal tail surface pivots','Only a small tab moves','The vertical stabilizer pivots','Both ailerons move together'],0,'A stabilator is an all-moving horizontal tail surface that provides pitch control.','Alternative controls','Stabilator'),
Q('Why is an antiservo tab commonly used with a stabilator?', ['It moves with the stabilator to increase control force and reduce over-sensitivity, and may also provide trim','It moves opposite the stabilator to make it more sensitive','It provides yaw damping only','It acts as a landing flap'],0,'Because stabilators can be very sensitive, antiservo tabs increase the pilot force required and can provide trim.','Alternative controls','Antiservo tab'),
Q('What is the primary aerodynamic effect of extending trailing-edge flaps for landing?', ['Increase lift coefficient and drag, allowing lower approach speed/steeper descent within limits','Reduce both lift and drag','Increase stall speed in all cases','Eliminate the need for pitch control'],0,'Flaps change wing camber and often effective area, increasing lift and drag.','Secondary controls','Flaps'),
Q('A pilot extends flaps at an airspeed above the published flap operating limit. Why is this unsafe?', ['Aerodynamic loads on the flap system may exceed design limits','The flaps cannot create drag above that speed','The pitot tube will freeze','The rudder becomes ineffective'],0,'Flap speed limitations protect the flap structure and mechanism from excessive aerodynamic loading.','Secondary controls','Flap limitations'),
Q('A pilot retracts flaps abruptly immediately after takeoff while only slightly above stall speed. What is the main aerodynamic risk?', ['The sudden loss of flap-produced lift can cause the airplane to settle or stall if speed/angle of attack margin is inadequate','Retracting flaps always causes an immediate climb','Stall speed decreases instantly to zero','Drag increases so much the airplane stops'],0,'Flap retraction reduces lift coefficient and can increase stall speed; it should be performed according to the aircraft procedure with adequate airspeed and climb margin.','Secondary controls','Flap retraction'),
Q('What do spoilers primarily do when deployed?', ['Reduce lift and usually increase drag','Increase lift with no drag','Control pitch by increasing tail lift only','Change propeller RPM'],0,'Spoilers disturb airflow over the wing, reducing lift and adding drag.','Secondary controls','Spoilers'),
Q('A pilot deploys speed brakes/spoilers during descent. What should the pilot anticipate?', ['A change in lift/drag and possibly pitch that may require attitude or power adjustment','No change in flight path','A guaranteed stall','A magnetic compass error only'],0,'Lift-reducing/drag-producing devices change the airplane’s aerodynamic balance and may require compensation.','Secondary controls','Spoiler effects'),
Q('What feature of differential ailerons helps reduce adverse yaw?', ['The up-going aileron deflects more than the down-going aileron, increasing drag on the descending wing relative to a symmetric system','Both ailerons move down equally','The rudder is mechanically disconnected','Flaps deploy automatically with roll input'],0,'Differential deflection is designed to reduce the drag imbalance that causes adverse yaw.','Aileron design','Differential ailerons'),
Q('How do Frise-type ailerons help reduce adverse yaw?', ['The leading edge of the up-going aileron projects into the airflow, increasing drag on that wing','Both ailerons move in the same direction','They eliminate the need for roll control','They increase drag only on the rising wing'],0,'A Frise aileron adds drag on the wing with the up-going aileron, helping offset adverse yaw.','Aileron design','Frise ailerons'),
Q('A pilot enters a steep turn using aileron only and no rudder. What cockpit indication would most clearly reveal uncoordinated flight?', ['The slip/skid indicator displaced from center','The altimeter setting window','The tachometer','The fuel gauge'],0,'Uncoordinated yaw/sideslip is shown by the slip/skid indication and can also be felt physically.','Control coordination','Slip and skid'),
Q('A pilot intentionally holds opposite rudder and aileron on final to correct for a crosswind. What is this maneuver called?', ['A sideslip/cross-control technique','A coordinated constant-altitude turn','A chandelle','A power-off stall'],0,'Opposite aileron and rudder can create a sideslip used to control drift and align the longitudinal axis with the runway.','Control coordination','Sideslip'),
Q('Why does rudder effectiveness generally change with airspeed?', ['Aerodynamic force on the rudder depends on airflow/dynamic pressure over the surface','Rudder force depends only on aircraft weight','The rudder is electrically disabled at high speed','Yaw control comes only from the nosewheel'],0,'Control-surface aerodynamic authority varies with airflow, among other factors.','Primary controls','Control effectiveness'),
Q('A pilot makes a large abrupt control input at high airspeed. Why can control loads become dangerous even if the airplane does not stall?', ['Dynamic pressure is high, so large surface deflections can generate very large aerodynamic forces and structural loads','High speed eliminates aerodynamic force','Control surfaces stop moving above maneuvering speed','Only engine thrust creates structural loads'],0,'Control effectiveness and loads increase with dynamic pressure; abrupt inputs can overstress the airplane outside appropriate limits.','Control forces','High-speed control inputs'),
Q('Why are mechanical stops used in many flight-control systems?', ['Limit control-surface travel to approved ranges','Automatically coordinate every turn','Set the altimeter','Prevent trim use'],0,'Stops prevent surface movement beyond the designed/approved deflection range.','Control systems','Control stops'),
Q('A preflight check finds a control surface moves opposite to the cockpit control input. What should the pilot do?', ['Do not fly; the control-system discrepancy must be corrected','Fly slowly and compensate with trim','Assume the system will reverse itself after takeoff','Use rudder to replace all other controls'],0,'Correct control direction and freedom of movement are fundamental preflight checks; reversed rigging can be catastrophic.','Control systems','Preflight control check'),
Q('A pilot feels binding or unusual resistance during a full and free control check. What is the correct interpretation?', ['Treat it as a control-system discrepancy and resolve it before flight','Binding is normal in cold weather','Apply greater force until the control moves','Trim it out and depart'],0,'Controls must move freely and correctly through the required range; binding can indicate obstruction, damage, or misrigging.','Control systems','Control freedom'),
Q('What is the primary benefit of a balance tab?', ['It uses aerodynamic force on a small tab to reduce the pilot force required to move the main control surface','It increases pilot force to prevent overcontrol','It changes the aircraft CG','It acts as a static wick'],0,'A balance tab moves in a way that assists movement of the primary surface and reduces control force.','Tabs','Balance tab'),
Q('How does a servo tab differ from a conventional trim tab?', ['Pilot input moves the servo tab and aerodynamic force on the tab moves the primary control surface','A servo tab is fixed on the ground only','A servo tab has no aerodynamic function','A trim tab is the only surface that ever moves'],0,'Servo tabs use aerodynamic force to move or assist the main control surface; trim tabs primarily relieve steady control pressure.','Tabs','Servo tab'),
Q('Why is correct flap, trim, and control configuration important before takeoff?', ['Improper configuration can change lift, drag, control forces, and takeoff performance enough to prevent safe liftoff or climb','Configuration affects only passenger comfort','Trim has no effect until cruise','Flaps cannot affect stall speed'],0,'Takeoff configuration directly affects pitch forces, lift/drag, stall margin, and performance.','Secondary controls','Takeoff configuration'),
Q('A pilot experiences a runaway electric pitch trim. What is the fundamental aerodynamic concern?', ['The trim system can drive the airplane toward large sustained control forces or an undesired pitch tendency, requiring prompt aircraft-specific corrective action','Trim cannot affect pitch','The engine will automatically shut down','Only roll control is affected'],0,'Runaway trim can create large out-of-trim forces. Pilots must know and follow the aircraft-specific procedure while maintaining control.','Trim systems','Runaway trim','advanced'),
Q('Why should pilots learn the exact flight-control system of each airplane instead of relying only on generic knowledge?', ['Control linkages, tabs, trim, flap systems, autopilots, and limitations vary by aircraft, so aircraft-specific procedures and failure modes matter','Every airplane uses identical controls and limitations','Generic knowledge legally replaces the POH','Only jets have unique control systems'],0,'Basic principles transfer, but implementation and procedures are aircraft specific.','Control systems','Aircraft-specific controls'),
Q('What is the best operational summary of flight controls?', ['Primary controls command attitude about the three axes, while coordinated use, trim, and secondary controls shape the flight path and workload within aircraft limitations','The elevator controls altitude, ailerons control heading, and rudder controls airspeed in every condition','Trim should be used instead of primary controls','Each control affects only one variable and never interacts with the others'],0,'Pilots use coordinated primary controls to set attitude and flight path, then power, trim, and secondary controls to manage performance and workload.','Control coordination','Operational synthesis')
]

chapters[7]=[
Q('During the before-takeoff magneto check, one magneto produces an excessive RPM drop. Why is this significant?', ['The engine ignition system may not be operating within limits, so the discrepancy should be resolved before takeoff','Magnetos are used only for the starter','An RPM drop proves the alternator is charging','The engine will run normally because aircraft ignition depends on the battery'],0,'Most reciprocating aircraft engines use dual, engine-driven magnetos. An abnormal check can indicate ignition-system problems that affect power and reliability.','Ignition','Magneto check'),
Q('An aircraft experiences a total alternator failure in cruise, but the engine continues running normally. Why?', ['The magnetos provide ignition independently of the main electrical system','The battery directly powers the spark plugs indefinitely','The propeller no longer needs ignition in flight','The pitot-static system powers the engine'],0,'Engine-driven magnetos generate ignition energy independently, so a main electrical failure does not normally stop a conventional magneto-ignition engine.','Ignition','Independent ignition'),
Q('A carbureted engine begins running rough with a gradual RPM loss in conditions favorable for carburetor icing. What is the most likely mechanism?', ['Ice restricts airflow in the carburetor and disturbs the fuel-air mixture','The magnetos freeze internally','Fuel octane increases','The oil becomes too thin'],0,'Fuel vaporization and pressure drop can cool the carburetor throat enough for ice to form and restrict airflow.','Induction','Carburetor ice'),
Q('Why can carburetor ice form when outside air temperature is above freezing?', ['Vaporization and pressure drop in the carburetor can lower internal temperature substantially below ambient','Ice can form only below 0 °F','The exhaust system cools the carburetor','The fuel tank always contains ice'],0,'The carburetor can experience a significant temperature drop, so icing is possible in temperatures well above freezing when moisture is present.','Induction','Carburetor icing conditions'),
Q('When carburetor heat is applied to an engine already experiencing carburetor ice, what initial engine response may occur?', ['Additional roughness or RPM loss as melting ice/water passes through, followed by improvement if ice is removed','Immediate large power increase with no change in mixture','The propeller stops','Oil pressure always rises'],0,'Hot air is less dense and melting ice can temporarily worsen roughness before normal airflow returns.','Induction','Carburetor heat use'),
Q('Why does full carburetor heat normally reduce engine power even when no ice is present?', ['Heated induction air is less dense, reducing the mass of oxygen entering the engine','It changes the magneto timing','It raises fuel octane','It increases propeller blade area'],0,'Warmer air is less dense, so the engine receives less oxygen for combustion at a given throttle setting.','Induction','Carb heat performance'),
Q('At a high-density-altitude airport, a normally aspirated engine is operated with an excessively rich mixture for takeoff. What is the likely effect?', ['Reduced power because the fuel-air mixture contains too much fuel for the reduced mass of air','Higher power because more fuel always means more power','No effect because mixture matters only in cruise','The alternator output doubles'],0,'As air density decreases, an overly rich mixture can reduce combustion efficiency and available power.','Fuel-air mixture','Mixture control'),
Q('Why must a pilot follow the aircraft-specific mixture procedure rather than applying one universal leaning technique?', ['Engine type, fuel system, instrumentation, operating phase, and manufacturer limitations differ','All engines require exactly the same mixture setting','Mixture affects only fuel quantity indication','Leaning is prohibited in piston aircraft'],0,'Proper mixture management is aircraft/engine specific and must follow approved procedures and instrumentation.','Fuel-air mixture','Mixture procedures'),
Q('What is detonation?', ['Abnormally rapid, explosive combustion of the remaining charge after normal ignition has begun','Ignition before the spark event caused by a hot spot','Normal flame-front travel','Loss of electrical power'],0,'Detonation is uncontrolled explosive combustion after ignition, producing high pressures and temperatures that can damage the engine.','Combustion','Detonation'),
Q('What is preignition?', ['The fuel-air charge ignites before the normal spark because of a hot spot in the cylinder','The mixture burns too slowly after ignition','The magneto fires after the exhaust valve opens','The starter engages in flight'],0,'Preignition occurs when a hot spot ignites the mixture before the normal spark, causing damaging pressure and temperature effects.','Combustion','Preignition'),
Q('A pilot suspects detonation or excessive cylinder temperature in climb. Which general response reduces the condition?', ['Reduce engine stress according to the POH—such as lowering power/increasing cooling airflow and correcting mixture as applicable','Increase power and continue climbing steeply','Close all cowl flaps if installed','Lean aggressively regardless of engine guidance'],0,'Detonation risk is reduced by lowering temperature and pressure and following the engine manufacturer’s operating procedure.','Combustion','Engine temperature management'),
Q('Why is engine oil considered both a lubricant and a cooling medium?', ['It reduces friction and carries heat away from internal engine components','It provides ignition voltage','It creates lift on the propeller','It pressurizes the pitot tube'],0,'Oil lubricates moving surfaces and absorbs/transfers heat while also helping clean, seal, and protect components.','Lubrication','Oil functions'),
Q('Oil pressure drops toward zero while oil temperature begins rising. What should the pilot suspect?', ['A potentially serious lubrication-system problem requiring prompt action under the aircraft checklist','Normal warm-up behavior in cruise','A pitot blockage','A low battery only'],0,'Loss of oil pressure can quickly lead to engine damage; rising temperature reinforces the seriousness of the indication.','Lubrication','Oil-system failure'),
Q('Why is cylinder-head temperature important on an air-cooled piston engine?', ['Excessive temperature can lead to detonation, preignition, loss of strength, and engine damage','It determines magnetic heading','It measures fuel quantity','It is used only for cabin heat'],0,'Cylinder temperature is a key indication of thermal stress and proper engine cooling.','Cooling','Engine temperature'),
Q('What is the basic purpose of cowl flaps when installed?', ['Regulate cooling airflow through the engine compartment','Control wing camber','Direct fuel between tanks','Adjust propeller pitch directly'],0,'Cowl flaps change cooling-air flow and drag to manage engine temperature.','Cooling','Cowl flaps'),
Q('A fixed-pitch propeller is described as a compromise. Why?', ['Its blade angle cannot optimize efficiency for both low-speed climb and high-speed cruise','It changes blade angle automatically with RPM','It produces no thrust at low speed','It requires hydraulic pressure to hold pitch'],0,'One fixed blade angle must serve a wide range of speeds and power settings, so it cannot be optimal everywhere.','Propellers','Fixed-pitch propeller'),
Q('What does a constant-speed propeller governor attempt to maintain?', ['Selected propeller RPM by changing blade angle','Constant manifold pressure regardless of throttle','Constant airspeed in all attitudes','A fixed blade angle'],0,'The governor varies propeller blade angle to keep RPM near the selected value as power and airspeed change.','Propellers','Constant-speed propeller'),
Q('In a constant-speed propeller airplane, why are throttle and propeller controls considered separate?', ['Throttle primarily affects engine power/manifold pressure while the propeller control selects governing RPM, within operating procedures','Both controls always move the same mechanism','The propeller control sets fuel octane','Throttle changes only electrical power'],0,'Power and propeller speed are managed through distinct controls in typical constant-speed installations and must be coordinated per the POH.','Propellers','Power management'),
Q('An alternator fails at night. What is the key energy-management issue?', ['The battery becomes a finite source powering essential electrical loads, so load shedding and landing planning become important','The battery will recharge itself indefinitely','Magnetos will power all lights and radios','Electrical failure cannot affect avionics'],0,'With no charging source, the battery can supply electrical equipment only for a limited time.','Electrical','Alternator failure'),
Q('What is the primary function of a circuit breaker or fuse?', ['Protect wiring/equipment from excessive current by opening the circuit','Increase alternator voltage','Improve radio reception','Control fuel pressure'],0,'Circuit protection limits damage and fire risk from electrical faults or overloads.','Electrical','Circuit protection'),
Q('Why is repeatedly resetting a circuit breaker generally unsafe unless the checklist specifically directs it?', ['A tripped breaker may indicate a fault; repeated resets can overheat wiring or feed a fire','Circuit breakers are designed to be held closed manually','Resetting always repairs the failed component','Breakers control only nonessential equipment'],0,'A breaker can trip because of a real electrical fault. Re-energizing the fault may worsen damage or fire risk.','Electrical','Circuit-breaker discipline'),
Q('A fuel selector is positioned to an empty tank while a full tank remains available. What is the immediate engine risk?', ['Fuel starvation despite adequate total fuel aboard','Fuel exhaustion','Detonation from excess fuel','Carburetor icing only'],0,'Fuel starvation means usable fuel exists but is not reaching the engine due to selection, blockage, pump, or system configuration.','Fuel systems','Fuel starvation'),
Q('How does fuel starvation differ from fuel exhaustion?', ['Starvation means fuel is aboard but not reaching the engine; exhaustion means usable fuel has been consumed','They are identical terms','Exhaustion means the mixture is too lean','Starvation occurs only in turbines'],0,'The distinction matters during troubleshooting and prevention: one is delivery/configuration, the other is lack of usable fuel.','Fuel systems','Starvation versus exhaustion'),
Q('Why are fuel-tank vents important?', ['They allow pressure equalization so fuel can flow without a vacuum forming in the tank','They increase fuel octane','They cool the magnetos','They measure fuel quantity'],0,'A blocked vent can restrict fuel flow or deform a tank because fuel removal must be matched by air entering.','Fuel systems','Fuel venting'),
Q('Why should a pilot visually verify fuel quantity rather than relying only on cockpit fuel gauges when practical?', ['Fuel indications can be inaccurate or limited, and direct verification plus records/planning provides a stronger check','Fuel gauges are legally required to be exact at all quantities','Visual inspection changes fuel density','Only mechanics may read fuel gauges'],0,'Fuel planning should use multiple reliable sources because gauge limitations and human errors can lead to fuel mismanagement.','Fuel systems','Fuel quantity verification'),
Q('Why must the pilot sump fuel drains before flight when required by the aircraft procedure?', ['Water or contaminants can settle at low points and interrupt safe engine operation','Sumping increases octane','It checks battery voltage','It removes carburetor ice'],0,'Fuel samples help detect water, sediment, and wrong fuel at system low points before they reach the engine.','Fuel systems','Fuel contamination'),
Q('What is the fundamental reason supplemental oxygen becomes necessary as altitude increases?', ['Atmospheric pressure and therefore oxygen partial pressure decrease, reducing oxygen transfer to the body','The percentage of oxygen in the atmosphere rapidly falls to zero','Cabin temperature always drops below freezing','Nitrogen disappears'],0,'The oxygen percentage remains roughly constant, but lower total pressure reduces oxygen partial pressure and physiological availability.','Oxygen systems','Altitude physiology'),
Q('A pitot-heat switch, landing light, and electric fuel pump all use electrical power, but the engine uses magnetos for ignition. What practical lesson follows from that architecture?', ['An electrical-system failure may leave the engine running while removing important instruments, pumps, lights, or avionics, so the checklist and system knowledge matter','Electrical failure always stops a magneto engine immediately','Magnetos power every aircraft electrical load','The battery has no safety role'],0,'System independence can keep the engine operating while other critical capabilities degrade; pilots must understand which equipment depends on which source.','Electrical','System interdependence'),
Q('Why should a pilot know whether landing gear, flaps, fuel pumps, and deicing equipment are electrical, hydraulic, pneumatic, or mechanical on the specific airplane?', ['Failure symptoms and backup procedures depend on how each system is powered and actuated','All systems behave the same after a failure','The information matters only to mechanics','Power source cannot affect emergency procedures'],0,'Aircraft-specific system architecture determines indications, failure modes, and alternate/emergency operation.','Systems integration','Aircraft-specific systems'),
Q('What is the best operational summary of aircraft-systems knowledge?', ['Know what each system needs to function, how failure will present, what indications confirm it, and what the POH directs you to do','Memorize component names without understanding interactions','Assume redundancy makes failures unimportant','Troubleshoot from memory instead of using checklists'],0,'Useful systems knowledge lets a pilot recognize failures early, preserve critical functions, and execute aircraft-specific procedures correctly.','Systems integration','Operational synthesis')
]

chapters[8]=[
Q('The pitot opening becomes blocked but the drain hole remains open. What happens to the airspeed indicator?', ['It drops toward zero because pitot pressure vents away while static pressure remains available','It acts like an altimeter','It freezes at the last indicated airspeed','It reads true airspeed directly'],0,'With the ram-pressure opening blocked and the drain open, pitot pressure is lost and the airspeed indicator cannot sense the required pressure difference.','Pitot-static','Blocked pitot'),
Q('The pitot opening and drain hole both become blocked while the static source remains clear. During a climb, how will the airspeed indicator tend to behave?', ['It may increase like an altimeter because trapped pitot pressure is compared with decreasing static pressure','It must read zero','It remains exactly frozen at one value','It becomes a vertical-speed indicator'],0,'With pitot pressure trapped, a decrease in static pressure during climb increases the sensed differential and can produce an erroneously rising airspeed indication.','Pitot-static','Fully blocked pitot','advanced'),
Q('The static port becomes blocked while the pitot system remains clear. Which instruments are directly affected?', ['Airspeed indicator, altimeter, and vertical speed indicator','Tachometer, oil pressure, and compass','Attitude indicator only','Turn coordinator only'],0,'The ASI uses pitot and static pressure; the altimeter and VSI use static pressure.','Pitot-static','Blocked static source'),
Q('With a blocked static source, what happens to the altimeter once the blockage occurs?', ['It tends to remain at the altitude where static pressure became trapped','It always reads zero','It begins showing groundspeed','It indicates outside air temperature'],0,'The altimeter cannot sense subsequent ambient pressure changes when static pressure is trapped.','Pitot-static','Blocked static — altimeter'),
Q('With a blocked static source, what happens to the VSI after the trapped pressure equalizes internally?', ['It tends toward zero even during a climb or descent','It shows airspeed','It indicates magnetic heading','It always shows a climb'],0,'The VSI depends on changing static pressure and a calibrated leak; without ambient pressure changes entering the system, the differential decays toward zero.','Pitot-static','Blocked static — VSI'),
Q('A pilot flies from an area of high pressure to lower pressure without resetting the altimeter. Relative to indicated altitude, where is the airplane actually?', ['Lower than indicated','Higher than indicated','At exactly indicated altitude','The error affects only airspeed'],0,'From high pressure to low without resetting, true altitude is lower than indicated—the classic “high to low, look out below.”','Altimeter','Pressure error'),
Q('A pilot flies from warm air into much colder air while maintaining the same indicated altitude. What is the terrain-clearance risk?', ['True altitude can be lower than indicated in the colder air','True altitude must be higher than indicated','Temperature has no effect on true altitude','Only the VSI is affected'],0,'Cold-temperature conditions can place the aircraft lower than the indicated altitude derived from standard-atmosphere calibration.','Altimeter','Temperature error'),
Q('What does indicated altitude mean?', ['Altitude read directly from the altimeter when set to the current altimeter setting','Actual height above the terrain','Pressure altitude corrected for nonstandard temperature','GPS altitude only'],0,'Indicated altitude is the direct altimeter reading with the current local pressure setting applied.','Altimeter','Types of altitude'),
Q('What is pressure altitude?', ['Altitude indicated when the altimeter is set to the standard datum of 29.92 inHg','Height above ground level','Altitude corrected for temperature','True altitude above mean sea level with local setting'],0,'Pressure altitude is referenced to the standard pressure plane and is used in performance/density-altitude calculations.','Altimeter','Pressure altitude'),
Q('What is density altitude?', ['Pressure altitude corrected for nonstandard temperature, representing air-density effects on performance','Indicated altitude corrected for magnetic variation','Height above the runway','Altitude displayed only by GPS'],0,'Density altitude expresses the density of the air as an equivalent altitude in the standard atmosphere and is directly relevant to aircraft performance.','Altimeter','Density altitude'),
Q('Why is the airspeed indicator able to measure aerodynamic speed without directly measuring distance traveled?', ['It measures the difference between pitot total pressure and static pressure, which is related to dynamic pressure','It measures GPS position change','It counts propeller revolutions','It compares magnetic heading with time'],0,'The ASI converts pressure differential into an indicated speed calibrated to aerodynamic dynamic pressure.','Airspeed','ASI principle'),
Q('What is calibrated airspeed?', ['Indicated airspeed corrected for installation and instrument error','Indicated airspeed corrected only for wind','True airspeed corrected for groundspeed','Groundspeed corrected for magnetic variation'],0,'CAS corrects IAS for position/installation and instrument error.','Airspeed','CAS'),
Q('At higher altitude, why is true airspeed generally greater than indicated airspeed for the same indicated value?', ['Lower air density requires a higher actual velocity to produce the same dynamic pressure','The pitot tube measures groundspeed','The wing becomes larger with altitude','Magnetic variation increases'],0,'IAS reflects dynamic pressure; lower density requires greater true velocity to create the same dynamic pressure.','Airspeed','IAS versus TAS'),
Q('The white arc on a conventional airspeed indicator primarily identifies what range?', ['Flap operating range from VSO to VFE','Normal operating range from VS1 to VNO','Caution range from VNO to VNE','Best glide range'],0,'The white arc is the flap operating range.','Airspeed markings','White arc'),
Q('The green arc primarily represents what?', ['Normal operating range','Flap operating range only','Never-exceed range','Stall-warning range only'],0,'The green arc generally extends from VS1 to VNO and denotes the normal operating range.','Airspeed markings','Green arc'),
Q('What does the yellow arc signify?', ['Caution range to be used only in smooth air and with caution','Flap extension range','A prohibited range at all times','The range for best angle of climb'],0,'The yellow arc is a caution range between VNO and VNE on conventional markings.','Airspeed markings','Yellow arc'),
Q('What does the red radial line on the airspeed indicator indicate?', ['Never-exceed speed VNE','Best rate of climb speed','Maximum flap extension speed','Stall speed in landing configuration'],0,'The red line marks the never-exceed speed.','Airspeed markings','VNE'),
Q('A pilot levels off after a steady climb. Why does the VSI briefly lag before settling at zero?', ['The VSI uses a calibrated leak/restricted flow, so pressure inside the case changes with a time delay','The pitot tube warms slowly','The compass is precessing','The altimeter setting changes automatically'],0,'The VSI senses the rate of static-pressure change through a calibrated restriction, which creates inherent lag.','Vertical speed','VSI operation'),
Q('What gyroscopic property allows an attitude indicator to provide a stable reference?', ['Rigidity in space','Magnetic dip','Bernoulli pressure','Compass deviation'],0,'A rapidly spinning gyro tends to maintain its plane of rotation, providing a stable reference.','Gyroscopic instruments','Rigidity in space'),
Q('What is gyroscopic precession?', ['A force applied to a spinning gyro is manifested approximately 90° later in the direction of rotation','A gyro automatically aligns with magnetic north','A gyro measures static pressure','A gyro slows only at sea level'],0,'Precession describes the characteristic response of a spinning gyro to an applied force.','Gyroscopic instruments','Precession'),
Q('Why must many conventional heading indicators be periodically realigned with the magnetic compass?', ['Gyro friction and precession cause heading-indicator drift over time','The heading indicator senses pitot pressure','The compass has no errors','The heading indicator automatically tracks GPS instead of heading'],0,'Conventional directional gyros drift and require periodic comparison/realignment with the magnetic compass.','Gyroscopic instruments','Heading-indicator drift'),
Q('A pilot is turning from a northerly heading in the Northern Hemisphere using only the magnetic compass. Why can the compass initially indicate misleading turn behavior?', ['Magnetic dip produces turning errors that vary with heading and latitude','The compass uses pitot pressure','The gyro tumbles','Variation changes every second'],0,'Magnetic dip and compass construction cause northerly/southerly turning errors in addition to acceleration errors.','Magnetic compass','Turning errors'),
Q('During acceleration on an east or west heading in the Northern Hemisphere, what compass error should the pilot anticipate?', ['An apparent turn toward north; deceleration produces an apparent turn toward south','An apparent turn toward south during acceleration','No error on east/west headings','The compass freezes'],0,'The mnemonic ANDS describes acceleration north, deceleration south for east/west headings in the Northern Hemisphere.','Magnetic compass','Acceleration error'),
Q('What is magnetic variation?', ['The angular difference between true north and magnetic north at a location','Error caused by electrical equipment inside the airplane','Gyro drift over time','Difference between IAS and TAS'],0,'Variation is a geographic difference between the true and magnetic meridians.','Magnetic compass','Variation'),
Q('What is compass deviation?', ['Compass error caused by magnetic fields in the aircraft','Difference between true and magnetic north','Error from nonstandard temperature','Airspeed calibration error'],0,'Deviation is aircraft-specific magnetic interference and is accounted for using the compass correction card.','Magnetic compass','Deviation'),
Q('A pilot sees conflicting attitude information between the primary display and standby instrument. What is the correct conceptual response?', ['Cross-check independent instruments and supporting performance indications to identify the failed source rather than trusting one display blindly','Always trust the larger display','Always trust the newest instrument','Ignore all instruments and use the magnetic compass for pitch'],0,'Instrument cross-check and redundancy are used to detect failures and maintain control.','Electronic displays','Instrument cross-check'),
Q('Why can a glass-cockpit failure be especially hazardous if a pilot is not trained on reversionary or standby modes?', ['A single display or data-source failure may remove several integrated indications at once, increasing workload','Glass instruments cannot fail','Standby instruments are decorative','Electronic displays never share sensors'],0,'Integrated systems can concentrate information and failure effects; pilots need aircraft-specific knowledge of backup sources and reversion.','Electronic displays','Display failures'),
Q('An air data computer receives erroneous static pressure. Which displayed values may be affected simultaneously?', ['Altitude, vertical speed, and airspeed-related data','Magnetic compass direction only','Engine oil pressure only','Fuel quantity only'],0,'Air-data systems derive multiple flight parameters from shared pitot/static/temperature inputs, so one sensor error can affect several indications.','Electronic displays','Shared data sources'),
Q('Why is “trust but verify” a useful instrument-flight habit even in VFR operations?', ['No single instrument should replace outside references and cross-check; unusual indications should be compared with independent cues','Airspeed indicators are intentionally inaccurate','The pilot should constantly distrust every instrument','Only the GPS is reliable'],0,'Cross-check helps detect instrument failures and prevents fixation, while outside visual references remain primary when appropriate in VMC.','Instrument scan','Cross-check'),
Q('What is the best operational summary of flight-instrument knowledge?', ['Understand each instrument’s data source, normal behavior, errors, and failure indications so conflicting information can be recognized and managed','Memorize only the color arcs','Assume all instruments fail independently','Use one favorite instrument as the sole source of truth'],0,'Practical instrument knowledge is about sources, limitations, cross-check, and failure recognition.','Instrument scan','Operational synthesis')
]

chapters[9]=[
Q('A pilot wants to know the maximum demonstrated crosswind, approved weight limits, and emergency procedures for a specific airplane. What is the primary source?', ['The aircraft AFM/POH and its approved supplements','A generic flight-training handbook','A sectional chart','The AIM only'],0,'Aircraft-specific limitations, procedures, and performance information belong in the approved AFM/POH and supplements.','AFM/POH','Aircraft-specific information'),
Q('A pilot finds a placard in the cockpit that conflicts with a remembered limitation from another aircraft of the same model family. What should the pilot do?', ['Follow and verify the limitation applicable to the specific aircraft; placards and approved documents are part of its operating limitations','Use the remembered value because all airplanes of one model are identical','Ignore placards if the pilot has more experience','Average the two values'],0,'Limitations can vary with serial number, equipment, modification, or supplement. The specific aircraft’s approved information controls.','AFM/POH','Limitations'),
Q('Which AFM/POH section is designed to be the first place to look for approved operating limitations?', ['Limitations','Performance','Weight and Balance','General'],0,'The standardized POH format places operating limitations in Section 2.','AFM/POH','POH sections'),
Q('Which AFM/POH section is the primary source for immediate and expanded emergency procedures?', ['Emergency Procedures','Normal Procedures','Supplements','Handling and Care'],0,'Emergency procedures are organized in Section 3 of the standardized format.','AFM/POH','POH emergency section'),
Q('A pilot is preparing for a normal cold start, taxi, run-up, takeoff, and landing. Which POH section is the normal primary reference?', ['Normal Procedures','Limitations only','Performance only','Index of supplements'],0,'Normal operating checklists and expanded procedures are found in the Normal Procedures section.','AFM/POH','POH normal procedures'),
Q('A pilot needs takeoff distance, climb rate, cruise, and landing performance for today’s conditions. Which POH section is most relevant?', ['Performance','General','Emergency Procedures','Handling and Care'],0,'Aircraft performance charts/tables are in the Performance section.','AFM/POH','POH performance'),
Q('Why must a pilot review aircraft supplements when installed equipment has been added?', ['A supplement can introduce new limitations, procedures, and performance information that become part of the operating information for that configuration','Supplements are advertising only','A supplement applies only to mechanics','Installed equipment never changes operation'],0,'Approved equipment and modifications can require supplemental limitations and procedures.','AFM/POH','Supplements'),
Q('Which documents are commonly remembered by the acronym ARROW for an airplane operation?', ['Airworthiness certificate, Registration certificate, Radio station license when required internationally, Operating limitations, Weight and balance data','AIM, Radar certificate, Runway diagram, Oxygen log, Weather chart','Airman certificate, Registration, Radio log, Oil analysis, Weight ticket','Airworthiness directive, Repair manual, Route clearance, Operations specification, Warranty'],0,'ARROW is a common memory aid for aircraft documents/information required aboard or available as applicable; exact requirements depend on the operation.','Required documents','ARROW'),
Q('A pilot discovers the aircraft registration certificate is missing before flight. Why can this be more than an administrative issue?', ['Required aircraft documents are part of legal operation; the discrepancy must be resolved before flight','Registration is needed only for maintenance','A photocopy always replaces the original without conditions','Registration affects only insurance'],0,'Aircraft registration is one of the required aircraft documents under applicable rules.','Required documents','Registration'),
Q('What is the practical purpose of an aircraft airworthiness certificate?', ['It indicates the aircraft was found to conform to its type design/approved condition at issuance and is authorized for operation when maintained and operated as required','It guarantees the aircraft can never become unairworthy','It certifies the pilot’s competence','It records fuel quantity'],0,'The certificate is part of the aircraft’s legal status, but continued airworthiness depends on maintenance, condition, and compliance.','Required documents','Airworthiness certificate'),
Q('A pilot sees that an Airworthiness Directive applies to the aircraft and its compliance time has passed. What is the correct conclusion?', ['The aircraft may not be airworthy until the applicable AD requirement is complied with','ADs are optional suggestions','The pilot may defer any AD for 100 hours','A current annual inspection cancels all ADs'],0,'Airworthiness Directives are legally enforceable requirements for correcting unsafe conditions.','Maintenance records','Airworthiness Directives'),
Q('Why does a current annual inspection not by itself guarantee an aircraft is airworthy today?', ['The aircraft may have developed defects, exceeded other inspection intervals, or become noncompliant after the annual','Annual inspections legally guarantee condition for 12 months regardless of damage','Only the pilot certificate affects airworthiness after an annual','Maintenance discrepancies cannot arise between inspections'],0,'Airworthiness is a continuing condition; both required inspections and present condition/compliance matter.','Maintenance records','Continued airworthiness'),
Q('An airplane used to carry passengers for hire has additional inspection requirements compared with many private operations. What should the pilot do rather than assume one interval applies?', ['Determine the inspections required for the specific operation and aircraft under current regulations and maintenance program','Use the private-owner interval for every flight','Rely on the tachometer color arcs','Ask passengers whether the inspection is needed'],0,'Inspection requirements depend on operation and equipment; pilots must verify the applicable program and dates.','Maintenance records','Inspection requirements'),
Q('A pilot finds an inoperative landing light before a daytime local flight. What is the correct decision process?', ['Determine whether the equipment is required by regulation, the aircraft type design/equipment list/KOEL, an AD, or the operation, then follow the authorized inoperative-equipment procedure','Remove the bulb and depart without documentation','Cancel every flight whenever any item is inoperative','Assume it is legal because the flight is in daylight'],0,'Inoperative equipment must be evaluated against all applicable requirements, then deactivated/removed/placarded and recorded as required.','Inoperative equipment','Decision process'),
Q('Why is a Minimum Equipment List (MEL), when specifically authorized for an aircraft/operation, different from simply deciding an item is unnecessary?', ['An MEL is an approved method that specifies conditions and procedures under which listed equipment may be inoperative','An MEL is a pilot-created wish list','An MEL removes all maintenance requirements','Every light airplane automatically has an MEL'],0,'An MEL provides approved relief with conditions; it is not a blanket permission to ignore failed equipment.','Inoperative equipment','MEL concept'),
Q('A pilot wants to use 14 CFR 91.213(d) for an inoperative item on an aircraft without an MEL. What is the key concept?', ['The pilot must systematically determine the item is not required by the applicable rules, certification basis, equipment list/KOEL, ADs, or kind of operation, then have it properly handled','Any item may be ignored if weather is VFR','Only avionics may be deferred','The pilot may disable safety equipment without evaluation'],0,'The no-MEL process still requires a structured legality and safety determination plus proper deactivation/removal and documentation.','Inoperative equipment','91.213 concept','advanced'),
Q('Why should pilots review maintenance logbooks when determining airworthiness rather than looking only at the panel?', ['Records show required inspections, AD compliance, maintenance entries, and status not visible during preflight','Logbooks are used only for resale value','A visual inspection proves all ADs are current','The POH contains all maintenance history'],0,'Airworthiness has both condition and records/compliance components.','Maintenance records','Logbook review'),
Q('A required inspection was signed off, but the pilot finds a fuel leak during preflight. Is the aircraft airworthy for flight?', ['No; current condition for safe operation is required in addition to paperwork','Yes; the inspection signoff overrides any new defect','Yes if fuel quantity is sufficient','Only a mechanic can notice a fuel leak'],0,'A pilot may not knowingly operate an aircraft that is not in condition for safe operation simply because records are current.','Airworthiness','Condition for safe operation'),
Q('What is the most important reason to use the checklist for the exact aircraft rather than a generic model checklist?', ['Installed equipment, modifications, serial-number differences, and approved procedures can change required actions','Generic checklists are always more conservative','All aircraft of one type have identical systems','Checklists are optional once memorized'],0,'Aircraft-specific configuration and supplements can change normal and emergency procedures.','AFM/POH','Aircraft-specific checklist'),
Q('A pilot wants to calculate current usable load. Why must the current weight-and-balance/equipment information be used instead of factory brochure data?', ['Equipment changes alter empty weight, moment, and useful load over the aircraft’s life','Factory brochure data legally overrides all later changes','Installed equipment has no weight','Only fuel changes the CG'],0,'The current aircraft empty-weight and equipment data reflect the actual configuration.','Weight and balance documents','Current equipment list'),
Q('What does a Type Certificate Data Sheet (TCDS) primarily describe?', ['Approved type-design data and limitations for the aircraft/engine/propeller type','The pilot’s medical qualifications','Current weather minima','ATC clearance procedures'],0,'A TCDS is an FAA document containing key certification data for a product type.','Certification documents','TCDS'),
Q('Why can Supplemental Type Certificate (STC) paperwork matter to a pilot?', ['An approved alteration can change configuration, limitations, procedures, or performance and may require a flight-manual supplement','STCs apply only to paint colors','An STC cancels the original airworthiness certificate','Pilots never need to know about installed modifications'],0,'STCs approve major design changes and can introduce operating information the pilot must know.','Certification documents','STC'),
Q('A pilot notices a required placard is unreadable. Why should that be corrected?', ['Placards can communicate approved limitations or required operating information and are part of the aircraft’s required configuration','Placards are decorative only','Only passengers use placards','A missing placard changes magnetic variation'],0,'Required markings and placards convey operating limitations and may be required for airworthiness.','Required documents','Placards'),
Q('Why is the equipment list operationally useful beyond maintenance bookkeeping?', ['It identifies installed equipment and weights/moments, helping determine current configuration and loading data','It replaces the POH emergency section','It provides ATC frequencies','It lists only optional paint schemes'],0,'Equipment records support weight and balance and confirm installed configuration.','Weight and balance documents','Equipment list'),
Q('A pilot wants to know whether a particular speed is a limitation or merely a recommended technique. What is the best approach?', ['Check the approved AFM/POH limitations and markings, then distinguish mandatory limitations from advisory guidance','Assume every speed in a training book is legally mandatory','Use social media consensus','Treat any memorized speed as a limitation'],0,'Aircraft documents identify approved limits, while other guidance may recommend techniques without changing legal limitations.','AFM/POH','Limitations versus guidance'),
Q('Why are operating limitations considered part of the aircraft’s required documentation even when displayed as placards or instrument markings?', ['They communicate approved boundaries needed to operate the aircraft safely and legally','They exist only for practical tests','They are optional if the pilot knows the airplane','They apply only during maintenance'],0,'Operating limitations may be contained in the AFM/POH, markings, and placards and are essential to approved operation.','Required documents','Operating limitations'),
Q('A pilot borrows an aircraft that has recently received a major avionics upgrade. What document check should be added to the normal review?', ['Look for applicable approved flight-manual supplements and revised weight-and-balance/equipment data','Ignore paperwork because avionics do not affect operation','Use only the original factory manual','Assume the installer explained everything to the owner'],0,'Major equipment changes can affect procedures, limitations, and weight/balance and often add supplements.','Certification documents','Post-modification documents'),
Q('If a pilot is unsure whether an inoperative item is legally deferrable, what is the safest course?', ['Stop and verify using the aircraft documents, current regulations, and qualified maintenance/operational guidance rather than guessing','Depart and research it after landing','Pull the circuit breaker without documenting it','Ask a passenger to decide'],0,'Airworthiness decisions should be based on the applicable approved and regulatory requirements, not assumption.','Inoperative equipment','Conservative airworthiness decision'),
Q('What is the central airworthiness responsibility of the PIC before flight?', ['Determine that required documents/inspections/compliance are in order and that the aircraft is in condition for safe operation','Assume the owner alone is responsible','Review only the fuel quantity','Delegate all airworthiness decisions to ATC'],0,'The PIC has an operational responsibility to ensure the aircraft is legally and physically airworthy for the intended flight.','Airworthiness','PIC airworthiness responsibility'),
Q('What is the best operational summary of Chapter 9 knowledge?', ['Know where the aircraft’s binding limitations and procedures live, how to verify inspection/compliance status, and how to make a disciplined inoperative-equipment decision','Memorize POH section numbers only','Assume a current annual makes every discrepancy legal','Use generic documents whenever the specific aircraft paperwork is unavailable'],0,'The practical goal is to connect aircraft documents and maintenance status to a defensible go/no-go airworthiness decision.','Airworthiness','Operational synthesis')
]

chapters[10]=[
Q('An airplane is loaded below maximum gross weight but the CG is aft of the approved limit. Is the aircraft acceptably loaded?', ['No; both weight and CG must remain within approved limits','Yes; staying below maximum weight is the only requirement','Yes if the runway is long','Only if the fuel tanks are full'],0,'Maximum weight and CG envelope are separate limits. An aircraft can be underweight and still be dangerously out of balance.','CG limits','Weight versus balance'),
Q('What is the basic formula for a weight-and-balance moment?', ['Weight × arm','Weight ÷ arm','Arm ÷ weight','Weight + arm'],0,'Moment is the turning effect of a weight about the datum and is calculated as weight multiplied by arm.','Calculations','Moment','advanced','calculation'),
Q('An airplane has a total moment of 120,000 lb-in and total weight of 1,600 lb. What is the loaded CG arm?', ['75.0 in','64.0 in','1,920 in','0.013 in'],0,'CG arm equals total moment divided by total weight: 120,000 ÷ 1,600 = 75.0 inches.','Calculations','CG calculation','advanced','calculation'),
Q('What is the datum in a weight-and-balance system?', ['A reference plane from which horizontal arms are measured','The aircraft center of lift','The runway threshold','The point where the airplane stalls'],0,'The manufacturer defines a datum so all component arms can be measured consistently.','Definitions','Datum'),
Q('A 50-lb bag is placed at an arm of 100 inches. What moment does it add?', ['5,000 lb-in','150 lb-in','2.0 lb-in','50,000 lb-in'],0,'Moment = 50 × 100 = 5,000 lb-in.','Calculations','Moment calculation','advanced','calculation'),
Q('A 100-lb item is moved from an arm of 40 inches to 70 inches. In which direction does the aircraft CG tend to move?', ['Aft, because the weight moved farther aft relative to the datum','Forward','It cannot change because total weight is unchanged','Toward the wingtip'],0,'Shifting weight changes total moment even when total weight is unchanged; moving a weight aft shifts CG aft.','CG movement','Weight shifting'),
Q('Why does an excessively aft CG reduce longitudinal stability?', ['The CG moves closer to the aerodynamic balance point, reducing restoring pitching moments','The tail becomes heavier','The engine produces more thrust','The wings lose area'],0,'Aft CG reduces the leverage/margin that provides pitch stability and can make stall/spin recovery more difficult.','CG effects','Aft CG'),
Q('Why can an excessively forward CG create takeoff/landing problems?', ['Greater tail force/elevator authority may be required to rotate or flare, and performance can be degraded','The airplane becomes too unstable in pitch','Stall speed always becomes zero','The rudder becomes reversed'],0,'Forward CG increases stability but requires greater balancing tail force and control authority and can increase drag/stall speed.','CG effects','Forward CG'),
Q('How does increasing aircraft weight generally affect stall speed?', ['It increases stall speed because more lift is required at a given flight condition','It lowers stall speed','It has no relationship to required lift','It affects only groundspeed'],0,'Heavier weight requires greater lift, leading to a higher stall speed for the same configuration and load factor.','Weight effects','Stall speed'),
Q('How does higher weight generally affect takeoff performance?', ['Longer takeoff distance and reduced acceleration/climb performance','Shorter ground roll and higher climb rate','No effect if CG is centered','It improves propeller efficiency enough to cancel the weight'],0,'More weight requires more lift and energy and generally reduces acceleration and climb performance.','Weight effects','Takeoff performance'),
Q('How does higher weight generally affect landing performance?', ['Higher approach/stall speeds and longer landing distance, all else equal','Lower touchdown energy and shorter landing distance','No change in kinetic energy','It eliminates ground effect'],0,'Heavier weight increases required lift speed and kinetic energy that must be dissipated during landing.','Weight effects','Landing performance'),
Q('An airplane is within CG limits at takeoff. Why must the pilot consider how fuel burn changes CG in flight?', ['Fuel has weight at a specific arm, so removing it can shift the CG depending on tank location','Fuel burn changes only total weight, never moment','CG is fixed once the engine starts','Only baggage can move CG'],0,'Fuel consumption removes both weight and moment. The resulting CG movement depends on tank location relative to the current CG.','CG movement','Fuel burn'),
Q('Fuel is stored well aft of the current CG. As fuel is burned, which way will CG generally tend to move?', ['Forward','Aft','Outboard only','It cannot move'],0,'Removing weight from aft of the CG reduces aft moment and tends to move the CG forward.','CG movement','Fuel burn direction'),
Q('Fuel is stored well forward of the current CG. As fuel is burned, which way will CG generally tend to move?', ['Aft','Forward','It remains fixed','Downward only'],0,'Removing a forward weight reduces forward moment and tends to shift CG aft.','CG movement','Fuel burn direction'),
Q('Why can loading a heavy passenger into an aft seat be more significant than loading the same passenger into a forward seat?', ['The larger arm produces a larger moment and therefore a greater CG shift','Weight changes depending on seat location','Aft passengers do not count toward gross weight','Only forward seats affect CG'],0,'Moment depends on both weight and arm, so the same weight creates more moment farther from the datum.','Calculations','Arm and moment'),
Q('What is useful load?', ['The difference between maximum allowable weight and basic empty weight, representing the load available for crew, fuel, baggage, etc. as defined for the aircraft','Only baggage capacity','Fuel capacity minus unusable fuel only','The maximum structural load factor'],0,'Useful load is the amount available for items added to the aircraft’s basic empty condition, subject to specific definitions and limits.','Definitions','Useful load'),
Q('Why does unusable fuel normally remain part of empty-weight accounting rather than payload planning?', ['It is fuel that cannot be safely used in flight and is included according to the aircraft’s empty-weight definition','It is considered baggage','It is ignored in all calculations','It always burns first'],0,'The approved weight-and-balance data defines what is included in basic empty weight, including unusable fuel under standardized definitions.','Definitions','Empty weight'),
Q('A loading calculation produces a CG inside the numeric limits, but the airplane exceeds maximum ramp/takeoff weight. Is it acceptable?', ['No; satisfying CG does not waive weight limits','Yes because balance is more important than weight','Yes if fuel will be burned after takeoff','Only on a cool day'],0,'All applicable weight limits and CG limits must be satisfied at the relevant phase of operation.','Weight limits','Multiple constraints'),
Q('Why can maximum ramp weight be higher than maximum takeoff weight?', ['It can allow for fuel expected to be burned during start and taxi before takeoff','Ramp weight excludes passengers','Takeoff weight ignores fuel','Ramp weight is an aerodynamic speed'],0,'Some aircraft allow a small additional ramp weight to account for fuel consumed before takeoff.','Weight limits','Ramp versus takeoff weight'),
Q('A pilot wants to shift CG forward without changing total weight. Which action would accomplish that?', ['Move an existing load from an aft station to a forward station','Add equal weight at the same station','Burn fuel from a forward tank','Move a forward load aft'],0,'Redistributing existing weight changes moment and CG without changing total weight.','CG movement','Weight shifting'),
Q('A pilot must add ballast to bring CG within limits. What is the key requirement?', ['Use the approved amount and location so both weight and CG limits remain satisfied and the ballast is properly secured','Place ballast anywhere convenient','Use loose objects so they can be moved in flight','Ignore ballast in the weight calculation'],0,'Ballast becomes part of the aircraft load and must be located, secured, and calculated using approved data.','Loading','Ballast'),
Q('Why is securely restraining baggage a weight-and-balance issue as well as a cabin-safety issue?', ['If a load shifts in flight, the aircraft CG and local loads can change unexpectedly','Once takeoff occurs, CG no longer matters','Baggage movement affects only passengers','A moving load loses weight'],0,'Load shift can change moment/CG and may create control problems in addition to injury or structural risk.','Loading','Load security'),
Q('A 20-lb item is moved 30 inches aft. By how much does total aircraft moment change?', ['It increases by 600 lb-in','It decreases by 600 lb-in','It increases by 50 lb-in','It does not change'],0,'Change in moment = weight × distance moved = 20 × 30 = 600 lb-in, aft in this case.','Calculations','Moment change','advanced','calculation'),
Q('An aircraft weighs 2,000 lb. How far must a 100-lb item be moved to shift the overall CG by 1 inch, ignoring other changes?', ['20 inches','10 inches','2 inches','200 inches'],0,'Weight moved × distance moved = total aircraft weight × desired CG shift, so 100 × d = 2,000 × 1; d = 20 inches.','Calculations','Weight-shift formula','advanced','calculation'),
Q('Why should pilots use current empty-weight and moment data after equipment changes?', ['Installing or removing equipment changes empty weight and moment, which changes every later loading calculation','Only maximum weight changes with equipment','Equipment has no moment if mounted inside the cabin','Factory data never becomes outdated'],0,'Weight-and-balance calculations are only as accurate as the aircraft’s current empty-weight/moment baseline.','Loading data','Current weight data'),
Q('An airplane is loaded near the aft CG limit. As passengers move farther aft in flight, what is the principal concern?', ['CG can move beyond the aft limit, reducing stability and recovery margins','The airplane becomes more longitudinally stable','Stall speed always decreases enough to make it safer','Only total weight matters after takeoff'],0,'Passenger movement changes moment and may shift CG outside the approved envelope.','CG effects','In-flight load movement'),
Q('Why can a forward CG increase fuel consumption or reduce performance?', ['More tail downforce may be required, so the wing must produce additional lift, increasing induced drag','Forward CG removes all induced drag','The propeller becomes larger','Fuel density increases'],0,'A forward CG typically increases stabilizing tail force and the total lift the wing must produce, increasing drag.','CG effects','Forward CG performance'),
Q('Why is an aft CG particularly concerning in a stall or spin?', ['Reduced longitudinal stability and reduced nose-down recovery tendency can make recovery more difficult','It guarantees the nose will drop more aggressively','It prevents the wing from stalling','It increases elevator authority in every direction without limit'],0,'Aft CG reduces restoring pitch stability and can reduce recovery margins.','CG effects','Aft CG recovery'),
Q('A pilot uses a loading graph instead of arithmetic. What must still be true for the result to be valid?', ['The graph must be the correct approved data for that aircraft/configuration and all weights/stations must be entered accurately','Any graph for the same manufacturer is acceptable','Graphs eliminate the need to check maximum weight','Only passenger weights need to be accurate'],0,'Graphical methods are just alternate ways to calculate moment/CG and depend on correct aircraft-specific data and inputs.','Calculations','Graphical method'),
Q('What is the best operational summary of weight and balance?', ['Before flight, verify every relevant weight limit and the CG envelope through the whole flight, and understand how loading location changes stability and performance','Total weight is the only meaningful number','CG matters only during landing','If the airplane physically fits the load, it is safe to fly'],0,'Safe loading is a combined weight, balance, structural, stability, and performance problem—not a single gross-weight check.','Weight and balance','Operational synthesis')
]

chapters[11]=[
Q('A normally aspirated airplane is departing a high-elevation airport on a hot afternoon. What combined performance change should the pilot expect?', ['Longer takeoff roll and reduced climb because high density altitude reduces engine, propeller, and wing performance','Shorter takeoff roll because true airspeed is higher','Higher engine power because the air is warmer','No change if indicated airspeed targets are unchanged'],0,'High density altitude means low air density. A normally aspirated engine develops less power, the propeller produces less thrust, and the wing needs greater true airspeed for a given indicated aerodynamic speed.','Density altitude','High-density-altitude performance'),
Q('Pressure altitude is 5,000 feet and the temperature is far above standard. Compared with 5,000 feet pressure altitude on a standard day, density altitude will be what?', ['Higher than 5,000 feet','Lower than sea level','Exactly 5,000 feet','Unaffected by temperature'],0,'Warmer-than-standard air is less dense, so density altitude rises above pressure altitude.','Density altitude','Temperature effect'),
Q('A strong headwind exists for takeoff. What happens to the ground distance needed to reach a given liftoff airspeed, all else equal?', ['It generally decreases because the required airspeed is reached at a lower groundspeed','It increases because the wing sees less airflow','It is unchanged because wind never affects takeoff ground roll','It doubles regardless of wind speed'],0,'A headwind reduces the groundspeed corresponding to a given airspeed, usually shortening ground roll.','Takeoff performance','Headwind'),
Q('A tailwind exists for landing. Why is landing distance normally increased?', ['For the same airspeed, groundspeed is higher, increasing kinetic energy and runway distance','The airplane stalls at a lower indicated speed','The brakes become stronger','The tailwind increases propeller thrust automatically'],0,'A tailwind raises touchdown groundspeed and kinetic energy, increasing distance and reducing safety margin.','Landing performance','Tailwind'),
Q('Why can even a modest tailwind percentage produce a disproportionately large increase in takeoff or landing distance?', ['Groundspeed and kinetic energy effects are nonlinear, and performance charts often show substantial penalties','Tailwinds reduce aircraft weight','Tailwinds eliminate induced drag','Runway friction always doubles'],0,'Performance penalties can grow quickly because energy varies with the square of speed and acceleration/deceleration margins are affected.','Takeoff and landing','Wind sensitivity'),
Q('A runway slopes uphill in the takeoff direction. What general performance effect should the pilot expect?', ['Longer takeoff roll because the airplane must accelerate against the uphill component of weight','Shorter takeoff roll because the nose is higher','No effect unless wind is calm','Higher climb rate after liftoff'],0,'An upslope opposes acceleration and generally increases takeoff distance.','Takeoff performance','Runway slope'),
Q('A runway is wet or contaminated. Why must dry-runway performance numbers not be assumed to apply?', ['Reduced tire friction and other surface effects can increase takeoff/landing distance and may require specific data or conservative margins','Water increases braking effectiveness','The wing produces more lift near a wet runway','Runway condition affects only taxiing'],0,'Surface condition can materially affect acceleration, braking, and directional control; aircraft-specific data and limitations should be used.','Takeoff and landing','Runway surface'),
Q('What speed gives the greatest altitude gain per unit of time under the stated aircraft conditions?', ['Vy','Vx','VNE','VSO'],0,'Vy is best rate of climb speed: maximum altitude gained per unit time.','Climb performance','Vy'),
Q('What speed gives the greatest altitude gain per unit of horizontal distance?', ['Vx','Vy','VNO','VA'],0,'Vx is best angle of climb speed: maximum altitude gain per unit horizontal distance.','Climb performance','Vx'),
Q('Why does the relationship between Vx and Vy change with altitude?', ['Available excess thrust and power change with altitude, altering the speeds for best angle and best rate','The wing chord changes with altitude','Gravity becomes zero','Airspeed indicators reverse at altitude'],0,'Climb performance depends on excess thrust/power, which changes with air density and engine/propeller performance.','Climb performance','Vx and Vy with altitude','advanced'),
Q('At the absolute ceiling, what is the airplane’s maximum steady rate of climb?', ['Zero','100 feet per minute','Vy','It equals Vx'],0,'At the absolute ceiling, maximum excess power is zero, so no steady climb is possible.','Climb performance','Absolute ceiling'),
Q('What is service ceiling?', ['The altitude at which maximum climb rate has decreased to a specified small value defined for the aircraft/category','The highest altitude permitted by ATC','The altitude at which the engine stops instantly','The altitude of maximum range'],0,'Service ceiling is a performance definition based on a specified residual climb rate, distinct from absolute ceiling.','Climb performance','Service ceiling'),
Q('A pilot wants maximum distance from a given amount of fuel in still air. What performance objective is being optimized?', ['Range','Endurance','Rate of climb','Stall margin only'],0,'Maximum range seeks the greatest distance per unit fuel.','Range and endurance','Range'),
Q('A pilot wants to remain airborne as long as possible with the available fuel. What objective is being optimized?', ['Endurance','Range','Groundspeed','Takeoff distance'],0,'Maximum endurance seeks maximum time aloft, not maximum distance.','Range and endurance','Endurance'),
Q('Why are maximum range and maximum endurance normally achieved at different operating conditions?', ['The condition that minimizes fuel used per distance is not generally identical to the condition that minimizes fuel used per unit time','Range and endurance are synonyms','Endurance always occurs at maximum power','Range is independent of drag'],0,'Range and endurance optimize different quantities and therefore can require different speeds/power settings.','Range and endurance','Range versus endurance'),
Q('An aircraft performance chart requires pressure altitude and temperature. Why is interpolation sometimes necessary?', ['Actual conditions often fall between published chart values, so a proportional estimate is needed within the chart’s intended method','Interpolation is used to correct magnetic variation','Charts are intentionally inaccurate','Interpolation replaces all manufacturer limitations'],0,'Published performance data often uses discrete values; interpolation estimates between them when appropriate.','Performance charts','Interpolation'),
Q('A takeoff chart gives 1,200 ft at 20 °C and 1,400 ft at 30 °C for the same other conditions. Using simple linear interpolation, what is the estimate at 25 °C?', ['1,300 ft','1,250 ft','1,400 ft','1,600 ft'],0,'25 °C is halfway between 20 and 30 °C, so a linear interpolation halfway between 1,200 and 1,400 gives 1,300 ft.','Performance charts','Interpolation','advanced','calculation'),
Q('Why should a pilot use the aircraft’s approved performance data rather than a generic rule of thumb when runway margin is limited?', ['Performance varies with aircraft, engine, propeller, weight, configuration, and conditions, and approved data accounts for the tested configuration','Rules of thumb are always more accurate','Generic data automatically includes runway slope','Approved data applies only to new airplanes'],0,'Aircraft-specific charts are based on the type/configuration and stated conditions; generic estimates can miss important factors.','Performance charts','Aircraft-specific data'),
Q('A performance chart assumes a paved, level, dry runway and proper technique. What should the pilot do if the actual runway is grass and wet?', ['Use applicable aircraft data or corrections and add conservative margins rather than applying the dry paved value unchanged','Use the dry number because grass improves braking','Subtract distance for the softer surface','Ignore runway condition if wind is calm'],0,'Chart assumptions matter. Deviating from them can significantly change performance.','Performance charts','Chart assumptions'),
Q('How does increased weight generally affect climb performance?', ['It reduces climb performance because more lift and power are required, leaving less excess power for climb','It increases climb rate','It has no effect below maximum gross weight','It increases propeller efficiency enough to cancel the weight'],0,'Higher weight increases required lift/drag and the power needed to maintain flight, reducing excess power available for climb.','Weight effects','Climb performance'),
Q('How does increased weight generally affect takeoff distance?', ['It increases takeoff distance','It decreases takeoff distance','It has no effect if CG is centered','It changes only landing distance'],0,'Heavier aircraft require more energy and higher lift speed, generally increasing takeoff distance.','Weight effects','Takeoff distance'),
Q('How does increased weight generally affect landing distance?', ['It increases landing distance because approach/touchdown speed and energy increase','It decreases landing distance','It affects only taxi distance','It has no effect with full flaps'],0,'More weight means more kinetic energy to dissipate and generally higher reference speeds.','Weight effects','Landing distance'),
Q('A pilot calculates a short-field takeoff that barely fits the available runway using book numbers. What is the strongest safety concern?', ['Published numbers assume specified technique/conditions and contain no guarantee for pilot technique, engine condition, surface, gusts, or measurement error, so meaningful margin is needed','Book numbers always include a 100% safety margin','Runway length is irrelevant once the chart says the flight is legal','Short-field technique can overcome any performance deficit'],0,'Performance planning should include realistic margins because actual conditions and technique may differ from test conditions.','Performance planning','Safety margin'),
Q('Why does high humidity slightly increase density altitude?', ['Water vapor is less dense than the dry-air molecules it replaces, reducing air density','Water vapor is heavier than nitrogen','Humidity raises atmospheric pressure at every altitude','It increases oxygen percentage'],0,'At the same pressure and temperature, moist air is slightly less dense than dry air.','Density altitude','Humidity'),
Q('An airplane lifts off normally at high density altitude but climbs poorly. Why is that possible?', ['Liftoff only demonstrates enough lift at that instant; reduced engine thrust/power and high true airspeed can still leave little excess performance for climb','Once airborne, density altitude no longer matters','Ground effect permanently increases climb rate','The altimeter overreads climb performance'],0,'High density altitude degrades both takeoff and climb; leaving ground effect can reveal inadequate excess power.','Density altitude','Post-liftoff climb'),
Q('What is the relationship between indicated airspeed and true airspeed at high density altitude for the same aerodynamic lift condition?', ['True airspeed is higher for approximately the same indicated airspeed','True airspeed is lower','They are always identical','Indicated airspeed becomes groundspeed'],0,'A given indicated airspeed corresponds to a given dynamic pressure; lower density requires greater true velocity.','Density altitude','IAS and TAS'),
Q('Why can a higher true airspeed at liftoff increase takeoff ground roll?', ['The airplane must accelerate to a higher groundspeed to reach the required aerodynamic airspeed, especially with little headwind','Higher true airspeed reduces energy required','The engine develops more power in thin air','The brakes are applied during takeoff'],0,'At low density, the required dynamic pressure occurs at greater true/groundspeed, requiring more acceleration distance.','Takeoff performance','True airspeed effect'),
Q('A pilot uses a climb chart based on maximum gross weight, but the airplane is substantially lighter. What general conclusion is safest?', ['Actual performance may be better, but the pilot should use approved chart methods rather than invent an unapproved correction','Performance must be exactly the same','The chart can be ignored','Climb rate will always double'],0,'Weight affects performance, but pilots should use the manufacturer’s approved data and interpolation/corrections when available.','Performance charts','Weight interpolation'),
Q('Why should pilots calculate performance before departure instead of relying on how the airplane “usually feels”?', ['Small changes in density altitude, weight, wind, runway, and obstacles can combine to erase familiar margins','Aircraft performance never changes much from day to day','Pilot experience replaces chart data','Performance planning is only required for commercial flights'],0,'Performance is highly condition dependent; preflight calculation reveals risks that are not obvious from habit.','Performance planning','Preflight calculation'),
Q('What is the best operational summary of aircraft performance knowledge?', ['Translate today’s weight, runway, wind, temperature, pressure, surface, and obstacles into aircraft-specific takeoff, climb, cruise, and landing margins before committing to the flight','Memorize one takeoff distance for the aircraft','Assume published maximum weight guarantees adequate climb','Use density altitude only when an airport is above 10,000 feet'],0,'Performance planning is the disciplined application of aircraft-specific data to actual conditions with conservative margin.','Performance planning','Operational synthesis')
]

chapters[12]=[
Q('Air temperature is 86 °F and dew point is 82 °F. What does the small temperature/dew-point spread suggest?', ['The air is close to saturation, so clouds, fog, or precipitation may develop if cooling continues','The air is extremely dry','Thunderstorms are impossible','Density altitude must be low'],0,'A small temperature/dew-point spread indicates high relative humidity and little cooling is needed to reach saturation.','Moisture','Temperature/dew point spread'),
Q('A clear, calm night follows a humid day. Which fog type is most likely near sunrise over inland terrain?', ['Radiation fog','Advection fog','Steam fog only','Upslope fog only'],0,'Radiational cooling under clear skies and light wind can cool moist surface air to its dew point.','Fog','Radiation fog'),
Q('Moist air moves over a colder surface and is cooled to saturation while wind continues. Which fog type is most likely?', ['Advection fog','Radiation fog','Ice fog only','Frontal fog only'],0,'Advection fog forms when moist air is transported over a colder surface and cooled to saturation.','Fog','Advection fog'),
Q('Wind pushes moist air up rising terrain until it cools to saturation. Which process is producing the cloud/fog?', ['Upslope cooling','Radiational heating','Subsidence warming','Evaporative heating'],0,'Forced ascent causes expansion and cooling; if saturation is reached, upslope clouds/fog can form.','Fog and clouds','Upslope process'),
Q('What three ingredients are fundamentally required for thunderstorm development?', ['Moisture, instability, and a lifting mechanism','Cold air, smooth winds, and high pressure','Dry air, stability, and subsidence','Fog, snow, and a temperature inversion'],0,'Thunderstorms require sufficient moisture, unstable air, and lift to initiate deep convection.','Thunderstorms','Ingredients'),
Q('Why are towering cumulus clouds a serious warning to a VFR pilot even before lightning is observed?', ['They indicate strong convective vertical currents that can rapidly develop into thunderstorms and severe turbulence','They always contain smooth air','They prove the atmosphere is stable','They occur only above icing levels'],0,'Rapid vertical cloud growth signals significant instability and powerful updrafts.','Thunderstorms','Convective development'),
Q('What is the safest general strategy for a small airplane confronted with a mature thunderstorm?', ['Avoid it by a wide margin rather than attempting to penetrate or “pick through” cells','Fly under the anvil to stay below hail','Pass between closely spaced cells using visual judgment alone','Climb above it if the airplane can reach the cloud top'],0,'Thunderstorms can contain extreme turbulence, hail, lightning, icing, wind shear, and severe vertical currents; avoidance is the primary strategy.','Thunderstorms','Avoidance'),
Q('Why can the area beneath a thunderstorm anvil be hazardous even if the airplane remains outside visible precipitation?', ['Hail can be thrown beyond the visible rain shaft and strong outflow/turbulence can extend outside the cell','Anvils contain no weather hazards','Only lightning exists under an anvils','Wind is always calm beneath the anvil'],0,'Thunderstorm hazards extend beyond the visible core; hail and outflow can occur outside the rain shaft.','Thunderstorms','Anvil hazards'),
Q('What is a microburst?', ['A concentrated downdraft that spreads outward near the surface and can produce severe wind shear','A weak updraft found only in winter','A small area of smooth high pressure','A type of radiation fog'],0,'Microbursts produce intense, rapidly changing wind vectors and are particularly dangerous during takeoff and landing.','Wind shear','Microburst'),
Q('On final approach, the airplane first gains airspeed in a headwind increase, then encounters a downdraft and tailwind. What hazard pattern does this suggest?', ['Microburst/wind-shear encounter','A stable warm front only','Normal sea-breeze circulation','Carburetor icing'],0,'A microburst can create a headwind gain followed by downdraft and tailwind, rapidly reducing performance near the ground.','Wind shear','Microburst sequence'),
Q('Stable air is most commonly associated with which conditions?', ['Stratiform clouds, smoother air, and potentially poor visibility in haze/fog','Strong vertical currents and towering cumuliform clouds','Severe convective turbulence by definition','Excellent visibility with dust-free air'],0,'Stable air resists vertical motion, favoring layered clouds and smoother conditions but often trapping haze and moisture.','Stability','Stable air'),
Q('Unstable air is most commonly associated with which conditions?', ['Cumuliform clouds, turbulence, showery precipitation, and generally better visibility between clouds','Only smooth stratiform clouds','Persistent temperature inversions with no vertical motion','Dense fog in every case'],0,'Unstable air supports vertical motion, convective clouds, turbulence, and showery precipitation.','Stability','Unstable air'),
Q('What does a temperature inversion do to vertical mixing?', ['It increases atmospheric stability and tends to suppress vertical mixing','It guarantees thunderstorms','It always improves visibility','It eliminates wind shear'],0,'Temperature increasing with height creates a stable layer that resists vertical displacement.','Stability','Temperature inversion'),
Q('Why can a strong inversion near the surface contribute to poor visibility?', ['Stable air traps moisture, smoke, and pollutants near the surface','It forces all contaminants upward rapidly','It removes relative humidity','It increases precipitation efficiency'],0,'Weak vertical mixing allows haze and contaminants to accumulate in the lower atmosphere.','Stability','Inversion and visibility'),
Q('A cold front approaches warm, moist, unstable air. What weather pattern is most likely?', ['Narrower band of more vigorous convection, gusty winds, and potentially thunderstorms','Only widespread smooth stratus with no wind change','No cloud development','Persistent radiation fog only'],0,'Cold fronts force warm air upward relatively rapidly, often producing stronger convective weather when moisture and instability are present.','Fronts','Cold front'),
Q('A warm front advances over retreating cold air. What general cloud/precipitation pattern is common?', ['Widespread layered clouds and precipitation developing ahead of the surface front','A narrow line of only severe thunderstorms in every case','Clear skies immediately ahead of the front','No visibility reduction'],0,'Warm air typically overruns a shallow cold air mass gradually, favoring extensive stratiform clouds and steady precipitation.','Fronts','Warm front'),
Q('Why is freezing rain especially dangerous to aircraft?', ['Supercooled large droplets can spread before freezing, producing rapid clear-ice accumulation beyond protected areas','It cannot freeze on moving aircraft','It produces only harmless rime ice','It occurs only above the tropopause'],0,'Freezing rain can create severe clear icing quickly and may overwhelm ice-protection systems.','Icing','Freezing rain'),
Q('What atmospheric conditions are generally required for structural icing?', ['Visible moisture and aircraft surfaces at or below freezing temperature','Dry air and high temperature','Only subzero air with no cloud or precipitation','High pressure and clear skies'],0,'Structural icing needs supercooled liquid water or suitable frozen/moisture conditions contacting a cold airframe.','Icing','Icing ingredients'),
Q('What characterizes rime ice compared with clear ice?', ['Rime tends to be rough, opaque, and formed from smaller droplets that freeze rapidly','Rime is always transparent and smooth','Rime cannot affect lift','Rime forms only on the ground'],0,'Rapid freezing traps air and creates an opaque, rough deposit.','Icing','Rime ice'),
Q('What characterizes clear ice?', ['Larger supercooled droplets spread before freezing, producing a harder, often transparent or translucent coating','It is soft frost that brushes off easily','It forms only from snow','It is aerodynamically harmless'],0,'Larger droplets freeze more slowly and can flow aft before solidifying, forming dense clear ice.','Icing','Clear ice'),
Q('Why can frost be dangerous even when it is very thin?', ['It roughens the airfoil surface, disturbing airflow and reducing lift while increasing drag','It increases wing camber in a beneficial way','It lowers stall speed','It matters only on propellers'],0,'Even small surface roughness can cause early separation and significant aerodynamic degradation.','Icing','Frost'),
Q('What causes wind in the atmosphere at the broadest level?', ['Pressure-gradient force, modified by Coriolis effect, friction, and terrain/local effects','Only Earth’s rotation','Only temperature at one point','Aircraft wake turbulence'],0,'Air accelerates from pressure differences, while rotation, friction, and terrain shape the resulting wind.','Wind','Wind forces'),
Q('Why does surface wind typically cross isobars toward lower pressure more than upper-level wind does?', ['Surface friction slows the wind and weakens Coriolis deflection, allowing a greater component toward low pressure','Pressure-gradient force disappears at the surface','Coriolis is stronger at zero wind speed','Isobars have no relation to pressure'],0,'Friction changes the force balance near the surface, causing wind to cross isobars toward lower pressure.','Wind','Surface friction'),
Q('A pilot expects strong winds aloft near a region where isobars are tightly packed. Why?', ['Closely spaced isobars indicate a strong horizontal pressure gradient','Tight spacing means pressure is identical everywhere','Isobars depict temperature only','Wind speed is independent of pressure gradient'],0,'A stronger pressure gradient generally produces stronger wind when other factors are comparable.','Wind','Pressure gradient'),
Q('What is the Coriolis effect?', ['The apparent deflection of moving air caused by Earth’s rotation','Friction between wing and air','Cooling caused by evaporation','The pressure drop in a carburetor'],0,'Earth’s rotation causes large-scale moving air to appear deflected relative to the surface.','Wind','Coriolis effect'),
Q('Why does rising unsaturated air cool?', ['As pressure decreases with height, the parcel expands and uses internal energy, producing adiabatic cooling','It absorbs heat from the Sun less efficiently','Oxygen concentration vanishes','Gravity directly removes heat'],0,'Expansion under lower ambient pressure causes adiabatic cooling.','Atmospheric processes','Adiabatic cooling'),
Q('Why is the saturated adiabatic lapse rate generally less than the dry adiabatic lapse rate?', ['Condensation releases latent heat, partly offsetting cooling','Saturated air stops expanding','Water vapor removes gravity','Pressure increases with height'],0,'Latent heat released during condensation reduces the rate of temperature decrease in saturated rising air.','Atmospheric processes','Latent heat','advanced'),
Q('A pilot sees lenticular clouds near a mountain range in strong winds. What operational hazard should be suspected?', ['Mountain-wave activity with potentially severe turbulence and strong vertical currents','Radiation fog only','A stationary warm front','Calm air throughout the lee side'],0,'Lenticular clouds are classic indicators of mountain waves and may be associated with severe turbulence and rotor activity.','Mountain weather','Mountain waves'),
Q('Why are rapidly changing surface winds near mountainous terrain a concern even in clear skies?', ['Terrain can create mechanical turbulence, rotors, downdrafts, and strong local wind gradients','Clear skies guarantee smooth air','Terrain affects only visibility','Mountain wind cannot influence takeoff or landing'],0,'Wind interacting with terrain can create hazardous vertical and horizontal flow even without clouds.','Mountain weather','Terrain-induced turbulence'),
Q('What is the best operational summary of weather theory?', ['Understand how moisture, stability, pressure, temperature, fronts, terrain, and convection create the conditions that affect aircraft performance and flight safety','Memorize cloud names without connecting them to processes','Assume legal visibility means weather risk is low','Use forecasts without understanding how weather can evolve'],0,'Weather theory lets pilots anticipate development and recognize when current observations may lead to hazardous future conditions.','Weather theory','Operational synthesis')
]

chapters[13]=[
Q('A pilot wants the latest routine surface observation at the destination. Which product is most directly relevant?', ['METAR','TAF','AIRMET','Winds aloft forecast'],0,'A METAR is a routine aviation surface weather observation.','Surface observations','METAR'),
Q('A rapidly changing airport condition triggers an unscheduled observation. Which product should the pilot expect?', ['SPECI','TAF only','Convective SIGMET','Area forecast'],0,'A SPECI is a special unscheduled surface observation issued when specified significant changes occur.','Surface observations','SPECI'),
Q('A pilot needs the expected ceiling, visibility, wind, and significant weather near a terminal several hours from now. Which product is designed for that?', ['TAF','METAR','PIREP','NOTAM'],0,'A Terminal Aerodrome Forecast provides expected meteorological conditions for the terminal area during its forecast period.','Forecasts','TAF'),
Q('Why should a pilot compare a TAF with current METARs and broader weather products rather than using the TAF alone?', ['A TAF is one forecast for a limited terminal area and time; actual trends and surrounding hazards require multiple sources','A TAF contains no weather information','METARs are forecasts of future conditions','Only one weather product may legally be used'],0,'A complete weather picture comes from integrating observations, forecasts, radar/satellite data, advisories, and pilot reports.','Weather briefing','Multiple products'),
Q('A pilot encounters unforecast moderate turbulence and icing. Which report can directly help other pilots and forecasters?', ['PIREP','TAF amendment only','Airport diagram','Chart Supplement'],0,'Pilot reports provide actual in-flight conditions such as turbulence, icing, cloud tops, and visibility.','Pilot reports','PIREP'),
Q('Why are PIREPs especially valuable?', ['They provide direct observations of conditions actually encountered aloft where surface systems may not measure them','They are always forecasts 24 hours in advance','They replace all weather radar','They are mandatory only after landing'],0,'PIREP information can confirm or contradict forecasts and reveal altitude-specific hazards.','Pilot reports','PIREP value'),
Q('An AIRMET is issued for moderate icing over a broad region. How should a light-aircraft pilot interpret it?', ['As an advisory for weather that can be hazardous, especially to light aircraft, requiring route/altitude/risk evaluation','As proof that flight is prohibited','As a guarantee that icing is severe everywhere in the area','As an airport closure notice'],0,'AIRMETs alert pilots to widespread conditions of concern; they do not mean the hazard is uniform at every point.','Advisories','AIRMET'),
Q('What distinguishes a SIGMET from an AIRMET at a high level?', ['A SIGMET addresses significant weather potentially hazardous to all aircraft, generally more severe/significant than AIRMET criteria','SIGMETs are only runway notices','AIRMETs apply only to jets','SIGMETs are surface observations'],0,'SIGMETs concern significant en route hazards to aircraft, while AIRMETs cover less severe but still important widespread conditions.','Advisories','SIGMET'),
Q('What does a Convective SIGMET identify?', ['Significant convective weather such as severe thunderstorms, embedded thunderstorms, or lines meeting issuance criteria','Only light rain','Mountain obscuration','Runway braking action'],0,'Convective SIGMETs highlight serious thunderstorm hazards.','Advisories','Convective SIGMET'),
Q('A pilot sees a NEXRAD image on an in-cockpit data-link display. Why should it not be used to weave between individual thunderstorm cells?', ['The image is delayed and composited; it is appropriate for strategic avoidance, not close tactical maneuvering around cells','NEXRAD shows only wind direction','Data-link weather is always real-time','Radar colors do not correspond to precipitation intensity'],0,'Data-link weather has collection, processing, transmission, and display latency. Conditions may have changed significantly since the depicted scan.','Data link weather','NEXRAD latency'),
Q('A data-link NEXRAD timestamp says the product is only a few minutes old. Why can the actual oldest precipitation data be older than that?', ['The displayed product time may not include all radar scan, mosaic, processing, and transmission delays','The timestamp always indicates the exact age of every pixel','Satellite clocks run slowly','Pilots are expected to add one hour by rule'],0,'Radar mosaics combine scans made at different times and then undergo processing/transmission, so displayed age can understate the age of some underlying data.','Data link weather','Product age','advanced'),
Q('What does airborne or ground-based weather radar primarily detect?', ['Energy returned by precipitation particles, used to infer precipitation location/intensity','Cloud temperature directly','Turbulence without any moisture in all cases','Surface visibility'],0,'Weather radar responds mainly to precipitation-sized particles; stronger returns generally indicate greater reflectivity, not a direct measurement of turbulence.','Radar','Radar fundamentals'),
Q('Why can an area behind an intense radar echo be misleadingly blank?', ['Attenuation can prevent radar energy from penetrating heavy precipitation, creating a radar shadow','Blank areas always mean clear air','Radar cannot display precipitation beyond 10 miles','Wind removes all droplets behind a storm'],0,'Strong precipitation can absorb/reflect so much energy that little returns from areas beyond it, masking hazards.','Radar','Attenuation'),
Q('A pilot receives a standard weather briefing several hours before departure and then delays the flight. What should happen before takeoff?', ['Update the weather and NOTAM information because conditions and advisories may have changed','Use the original briefing because it remains valid all day','Check only the destination METAR','No update is needed if the route is unchanged'],0,'Weather is time-sensitive; pilots should obtain current information appropriate to the actual departure time.','Weather briefing','Updating information'),
Q('What is the purpose of a standard preflight weather briefing?', ['Provide a comprehensive weather picture for the proposed flight, including adverse conditions, observations, forecasts, winds, and related information','Provide only destination wind','Replace pilot decision-making','Guarantee the flight will remain VFR'],0,'A standard briefing is intended to support a complete preflight risk assessment.','Weather briefing','Standard briefing'),
Q('When is an abbreviated briefing appropriate?', ['When the pilot needs specific additional information or an update to a previous briefing rather than a full briefing','As the only briefing before every cross-country','Only after landing','When the pilot wants to skip adverse weather'],0,'An abbreviated briefing supplements or updates existing information or addresses specific questions.','Weather briefing','Abbreviated briefing'),
Q('What is an outlook briefing intended for?', ['Planning a flight that begins beyond the normal standard-briefing time window','Reporting weather already encountered','Issuing ATC clearances','Replacing TAFs'],0,'Outlook briefings support early planning when the departure is sufficiently far in the future.','Weather briefing','Outlook briefing'),
Q('A winds-and-temperatures-aloft forecast shows substantially stronger headwinds at the planned altitude than lower down. What operational decision can this information support?', ['Selecting an altitude that balances wind, terrain, weather, performance, and fuel','Determining runway markings','Choosing magneto timing','Calculating baggage arm'],0,'Winds aloft directly affect groundspeed, time, fuel, and potentially turbulence/temperature considerations.','Forecasts','Winds aloft'),
Q('Why should pilots compare forecast winds aloft with actual groundspeed once airborne?', ['Large differences can reveal forecast error or stronger-than-expected winds and justify updating fuel/time decisions','Groundspeed is unrelated to wind','Forecasts are legally binding and cannot be wrong','Only ATC may compare forecast and actual wind'],0,'Actual performance should be compared with the plan so fuel and diversion decisions remain current.','Forecasts','Forecast verification'),
Q('A pilot sees temperature/dew-point values nearly equal in a METAR. What risk should be considered?', ['High relative humidity with potential low cloud/fog if conditions cool further','Guaranteed severe turbulence','No possibility of visibility restriction','A magnetic compass error'],0,'A small temperature/dew-point spread signals near-saturation and possible cloud/fog formation.','Surface observations','Temp/dew point'),
Q('A METAR reports gusty winds and a large wind-direction variation. Why is the full wind group operationally important?', ['Average wind alone can hide crosswind/gust changes that affect takeoff and landing control','Only the steady wind matters','Gusts affect only turbine aircraft','Runway alignment never matters'],0,'Wind variability and gusts change crosswind/headwind components and handling margins.','Surface observations','Wind interpretation'),
Q('Why must a pilot understand the observation time in a METAR?', ['Weather may have changed since the observation; age affects how representative the report is','METAR time is the forecast expiration time','Time is included only for recordkeeping','Observation time changes runway length'],0,'Weather products are snapshots; pilots must assess currency and trends.','Surface observations','Observation time'),
Q('A TAF includes a temporary group for lower ceilings during part of the forecast period. How should a pilot treat that?', ['As a forecast possibility that must be included in risk planning, especially if it would cross personal or legal limits','Ignore it because temporary conditions never occur','Treat it as a guaranteed continuous condition for the entire TAF','Assume ATC will keep the weather above minimums'],0,'Conditional/temporary forecast groups communicate meaningful uncertainty and should inform alternates, timing, and personal minimums.','Forecasts','TAF changes'),
Q('Why are graphical weather products useful but insufficient by themselves?', ['They provide spatial context but may simplify details, have update/latency limits, and should be combined with textual products and current observations','Graphics are always more precise than text','Text weather is obsolete','A single map contains every required detail'],0,'Good weather decisions synthesize multiple products and understand each product’s limitations.','Weather briefing','Graphical products'),
Q('What is the key limitation of satellite imagery for a pilot?', ['It depicts cloud/temperature-related information but does not directly tell the pilot every hazard, cloud base, or turbulence condition','It directly measures surface visibility everywhere','It replaces radar in thunderstorms','It shows exact icing severity in every cloud'],0,'Satellite imagery is valuable context but must be interpreted with other observations and forecasts.','Satellite','Satellite limitations'),
Q('What is the key limitation of radar reflectivity for turbulence decisions?', ['Strong precipitation often correlates with convective hazards, but radar does not directly display every turbulent region or vertical current','Radar directly measures all turbulence','No turbulence exists outside echoes','Weak echoes always mean smooth air'],0,'Radar reflectivity is a precipitation measurement; convective turbulence can extend beyond or differ from the strongest echoes.','Radar','Radar limitations'),
Q('Why is product latency especially important near fast-moving thunderstorms?', ['A cell can move, grow, or dissipate significantly during the delay between sensing and cockpit display','Thunderstorms are stationary','Latency affects only temperature forecasts','ATC automatically corrects every cockpit display'],0,'Convective weather evolves quickly, so stale data can materially misrepresent the present hazard location and intensity.','Data link weather','Latency risk'),
Q('A pilot’s tablet loses weather-data service in flight. What is the correct mental model?', ['The pilot must continue using available onboard/ATC/FSS resources and previously gathered information; data-link weather is a tool, not the sole safety system','The flight must continue unchanged because no new weather is needed','The tablet outage means the aircraft is unairworthy','The pilot should descend below all clouds immediately'],0,'Weather information management should have redundancy and contingency plans; loss of one source should trigger reassessment.','Data link weather','System failure'),
Q('Why is a weather briefing not simply a collection of products?', ['The pilot must integrate trends, uncertainty, route, altitude, aircraft capability, and escape options into a decision','Reading every product guarantees safety','Only the briefer is responsible for the go/no-go decision','A legal forecast means no further analysis is needed'],0,'Weather information becomes useful only when interpreted in the context of the specific flight and risk tolerance.','Weather briefing','Decision integration'),
Q('What is the best operational summary of aviation weather services?', ['Know what each product observes or forecasts, how current it is, what it cannot tell you, and combine multiple sources into a continuously updated flight decision','Memorize weather product abbreviations only','Use cockpit NEXRAD as real-time tactical radar','Rely on the destination forecast and ignore en route conditions'],0,'Safe weather use depends on product purpose, limitations, timing, and integration.','Weather briefing','Operational synthesis')
]

chapters[14]=[
Q('A pilot approaches a nontowered airport with no published special pattern. What pattern direction should normally be expected?', ['Left traffic unless markings, charted information, or other published procedures indicate otherwise','Right traffic at every airport','Straight-in only','Whichever direction gives the shortest route'],0,'Standard traffic patterns use left turns unless right traffic or another procedure is specified.','Traffic patterns','Pattern direction'),
Q('Why should a pilot avoid entering a nontowered traffic pattern in a way that disrupts established traffic?', ['Predictable pattern geometry helps pilots see, sequence, and avoid one another when no controller separates traffic','The pattern is only a noise-abatement suggestion','Other aircraft are required to avoid any arriving airplane','Straight-in entries always have priority'],0,'Consistency and predictability are central to collision avoidance at nontowered airports.','Traffic patterns','Predictability'),
Q('A pilot hears no radio calls at a nontowered airport. What should the pilot conclude?', ['The pattern may still contain aircraft without radios or with radio problems, so visual scanning remains essential','The airport is empty','The runway is closed','A radio call is equivalent to an ATC clearance'],0,'Radio use improves awareness but does not replace see-and-avoid or guarantee all traffic is transmitting.','Nontowered operations','See and avoid'),
Q('Runway 27 is aligned approximately with what magnetic direction?', ['270°','027°','180°','360°'],0,'Runway numbers represent magnetic direction rounded to the nearest ten degrees with the last zero omitted.','Runways','Runway numbering','application','calculation'),
Q('A runway designation changes from 17 to 18 after years of magnetic variation. Why can this happen?', ['Runway numbers are based on magnetic direction, which changes over time','The runway physically rotated','Runway numbers track field elevation','The airport changed ownership'],0,'Earth’s magnetic field changes, so the rounded magnetic runway designation can eventually require revision.','Runways','Magnetic runway numbers'),
Q('A pilot sees a red sign with white inscription “15-33.” What type of sign is this?', ['A mandatory instruction sign associated with a runway/critical area','A taxiway direction sign','An airport location sign','A destination sign'],0,'Red background with white inscription denotes mandatory instruction.','Airport signs','Mandatory signs'),
Q('A pilot sees a black sign with yellow inscription “A.” What does it generally indicate?', ['The taxiway on which the aircraft is currently located','A direction to Taxiway A','A runway holding position','An airport exit only'],0,'Black background with yellow inscription is a location sign.','Airport signs','Location signs'),
Q('A pilot sees a yellow sign with black inscription and an arrow pointing right toward “B.” What does it mean?', ['Taxiway B is in the indicated direction','The aircraft is currently on Taxiway B','Stop immediately for a runway','The runway is closed'],0,'Yellow background/black inscription with arrow is a direction sign.','Airport signs','Direction signs'),
Q('At a runway holding-position marking, which side contains two solid yellow lines and two dashed yellow lines?', ['The protected/runway side is beyond the dashed lines; an aircraft approaching from the taxiway side normally encounters the solid lines first','The dashed lines always face the taxiway','The marking has no directional meaning','The solid lines identify a parking area'],0,'When approaching a runway from a taxiway, pilots normally see the solid lines first and must not cross without appropriate authorization at a towered airport.','Airport markings','Runway hold marking'),
Q('A towered-airport pilot receives “Taxi to Runway 20 via Alpha, Bravo” without an explicit runway-crossing clearance. May the pilot cross an intervening runway?', ['No; runway crossings require an explicit clearance','Yes; “taxi to” automatically clears every runway crossing','Yes if no traffic is visible','Only at night'],0,'Modern taxi clearances require explicit authorization to cross a runway.','Taxi operations','Runway crossing clearance'),
Q('A pilot is unsure whether an ATC taxi instruction is understood correctly. What is the best action?', ['Stop or maintain a safe position and ask ATC for clarification before proceeding','Continue slowly and guess','Follow the aircraft ahead regardless of clearance','Enter the runway to get a better view'],0,'Uncertainty should be resolved before movement into a protected area; guessing is a runway-incursion hazard.','Taxi operations','Clarification'),
Q('ATC issues a taxi instruction the pilot cannot safely comply with because of aircraft limitations. What should the pilot say?', ['“Unable” and explain/request an alternative as needed','Accept it because ATC has final responsibility for aircraft limits','Remain silent and choose a different route','Turn off the radio'],0,'The PIC must not accept an unsafe instruction; “unable” clearly communicates the need for an alternative.','Taxi operations','Unable'),
Q('Why is an airport diagram useful before taxi at an unfamiliar towered airport?', ['It allows the pilot to pre-brief the route, runways, hot spots, and likely hold-short points before workload rises','It replaces all ATC instructions','It shows current weather radar','It authorizes runway crossings'],0,'Pre-taxi route planning reduces heads-down time and confusion during surface movement.','Taxi operations','Airport diagram'),
Q('What is a runway incursion?', ['Incorrect presence of an aircraft, vehicle, or person on the protected area of a surface designated for landing and takeoff','Any hard landing','A go-around caused by wind','Taxiing above normal speed'],0,'The definition focuses on unauthorized/incorrect presence on a runway protected area.','Runway safety','Runway incursion'),
Q('A pilot accidentally crosses a hold-short line without clearance. What should the pilot do?', ['Stop if safe and immediately advise ATC truthfully so the conflict can be managed','Continue and say nothing to avoid distraction','Take off without clearance','Turn off the transponder'],0,'Prompt communication allows ATC and other pilots to respond to the incursion.','Runway safety','Incursion response'),
Q('What do runway centerline lights or markings primarily help a pilot do?', ['Maintain alignment with the runway center','Determine magnetic variation','Identify taxiway names','Measure density altitude'],0,'Centerline cues support runway alignment during takeoff/landing and reduced visibility.','Airport markings','Runway centerline'),
Q('What does a displaced threshold mean for landing?', ['Landing touchdown is not authorized before the displaced threshold in the direction of displacement, though the pavement may be usable for certain other operations','The entire runway is closed','Takeoff is prohibited from both directions','The threshold is moved only on charts, not physically'],0,'A displaced threshold changes the portion available for landing from that direction; other uses depend on markings and published information.','Runways','Displaced threshold'),
Q('What is the purpose of runway end identifier lights (REIL)?', ['Rapidly identify the approach end of a runway','Show the runway centerline slope','Indicate a closed taxiway','Provide vertical glidepath information'],0,'REILs are synchronized flashing lights near the runway threshold that aid runway identification.','Airport lighting','REIL'),
Q('What does a PAPI provide?', ['Visual indication of the aircraft’s position relative to the desired glidepath','Runway remaining distance','Wind direction','Taxi route clearance'],0,'PAPI uses color combinations to show whether the airplane is above, on, or below the visual glidepath.','Airport lighting','PAPI'),
Q('A PAPI shows all red lights. What does that mean?', ['The aircraft is well below the glidepath','The aircraft is well above the glidepath','The aircraft is exactly on glidepath','The runway is closed'],0,'On a standard PAPI, more red indicates lower relative to glidepath; all red is well below.','Airport lighting','PAPI interpretation'),
Q('A PAPI shows two white and two red lights. What does that indicate?', ['Approximately on the glidepath','Well above glidepath','Well below glidepath','Taxiway alignment'],0,'Two white and two red is the standard on-slope indication.','Airport lighting','PAPI interpretation'),
Q('What is the purpose of an airport rotating beacon?', ['Help identify the location/type of a lighted airport at night and sometimes during reduced visibility','Indicate exact wind direction','Authorize landing','Show taxiway centerline'],0,'Airport beacons aid visual identification; light color combinations can indicate airport type.','Airport lighting','Beacon'),
Q('A windsock is fully extended across the runway direction. What operational information is most important?', ['It shows approximate wind direction and relative strength, alerting the pilot to a potentially significant crosswind','It provides exact wind speed to one knot','It replaces AWOS/ATIS','It identifies runway slope'],0,'A windsock is an approximate visual wind indicator useful for runway selection and crosswind awareness.','Airport indicators','Windsock'),
Q('Why should a pilot listen to ATIS/AWOS before entering a busy airport environment when available?', ['It provides current routine airport/weather information and reduces frequency congestion, allowing the pilot to prepare before contacting ATC','It grants landing clearance','It replaces NOTAM review','It gives aircraft maintenance status'],0,'Automated/broadcast information helps pilots obtain weather, runway, and operational details before radio workload increases.','Airport communications','ATIS/AWOS'),
Q('A pilot reads back a hold-short instruction incorrectly and the controller does not immediately notice. What remains the pilot’s responsibility?', ['Do not enter the runway unless the clearance is understood; ask for clarification if uncertain','Proceed because silence means approval','Follow the aircraft ahead','Ignore hold-short instructions in VMC'],0,'Runway entry requires clear authorization and pilot understanding; readback is not a substitute for comprehension.','Runway safety','Hold-short discipline'),
Q('At night, a pilot sees an illuminated large “X” at the runway end. What does it indicate?', ['The runway is closed','The runway has a displaced threshold','The runway is preferred for landing','The PAPI is out of service'],0,'An “X” is the standard closed-runway marking/lighting indication.','Airport markings','Closed runway'),
Q('Why should a pilot avoid heads-down programming while taxiing?', ['Taxi is a high-risk surface-navigation phase; distraction increases the chance of wrong turns, runway incursions, or collisions','GPS programming is required during every taxi','The airplane cannot turn while the pilot looks down','ATC assumes responsibility for obstacle avoidance'],0,'Surface movement demands outside visual attention and route awareness; programming should be done while stopped when possible.','Taxi operations','Heads-down distraction'),
Q('A pilot is approaching a runway at a complex airport and becomes uncertain of position. What is the safest action?', ['Stop in a safe location if possible and request progressive taxi or clarification','Continue moving to avoid blocking traffic','Enter the nearest runway and ask from there','Follow painted lines without knowing where they lead'],0,'Stopping before compounding the error preserves options; ATC can provide progressive taxi instructions.','Taxi operations','Lost on airport'),
Q('What is the best defense against runway confusion during departure?', ['Brief the assigned runway, taxi route, runway signs/markings, expected heading, and verify the runway before takeoff','Rely only on the aircraft ahead','Assume the longest pavement is the runway','Use GPS groundspeed to identify the runway'],0,'A pre-takeoff runway verification using signage, heading, and clearance prevents wrong-surface departures.','Runway safety','Runway verification'),
Q('What is the best operational summary of airport operations?', ['Plan the surface route, understand signs/markings/lights, maintain situational awareness and radio discipline, and never cross or enter a runway without clear authorization when required','Memorize sign colors only','Assume ATC prevents all surface conflicts','Use radio calls instead of visual scanning at nontowered airports'],0,'Safe airport operation combines visual knowledge, planning, communication, and disciplined runway-protection habits.','Airport operations','Operational synthesis')
]

chapters[15]=[
Q('A VFR pilot plans to enter Class B airspace. What must happen before entry?', ['An explicit ATC clearance into the Class B must be received','Two-way communications alone are always sufficient','Only a transponder code is required','No ATC contact is required in VMC'],0,'Class B entry requires an ATC clearance, not merely establishment of communications.','Controlled airspace','Class B entry'),
Q('A pilot calls a Class C approach facility with the aircraft callsign. ATC replies, “Aircraft calling, standby,” without using the callsign. Has two-way radio communication for Class C entry been established?', ['No; ATC must respond using the aircraft callsign or an abbreviated form that clearly identifies the aircraft','Yes; any voice response establishes communications','Yes if the transponder is on','No radio communication is ever required in Class C'],0,'For Class C/D entry, communication is considered established when ATC acknowledges the specific aircraft by callsign.','Controlled airspace','Class C communications','advanced'),
Q('A pilot approaching Class D calls the tower and hears, “Cessna 123AB, standby.” May the pilot continue into Class D, assuming no contrary instruction?', ['Yes; the tower has responded using the callsign, establishing two-way communications, though the pilot must still comply with ATC instructions','No; an explicit “cleared into Class D” is required','Only if the pilot is IFR','Only after receiving a landing clearance'],0,'Class D normally requires establishing two-way radio communication before entry; a callsign acknowledgment satisfies that communication requirement.','Controlled airspace','Class D communications'),
Q('What is Class A airspace in the contiguous United States primarily intended for?', ['High-altitude controlled operations conducted under IFR','Low-level uncontrolled VFR training','Only military operations','Traffic patterns at small airports'],0,'Class A generally begins at 18,000 feet MSL and is an IFR-only operating environment under the applicable rules.','Controlled airspace','Class A'),
Q('A pilot flying VFR sees that controlled airspace above is Class E. What does “Class E” mean?', ['Controlled airspace that is not Class A, B, C, or D','Uncontrolled airspace only','Special-use airspace in which flight is prohibited','Airspace used only by military aircraft'],0,'Class E is controlled airspace of various configurations not designated A–D.','Controlled airspace','Class E'),
Q('What is Class G airspace?', ['Uncontrolled airspace','The highest class of controlled airspace','A type of prohibited area','Any airspace inside a Class B shelf'],0,'Class G is airspace not designated as controlled airspace; VFR weather minima and services differ by altitude/time/location.','Uncontrolled airspace','Class G'),
Q('Why do VFR cloud-clearance and visibility requirements vary by airspace and altitude?', ['They provide different time-and-distance margins for see-and-avoid based on traffic environment and expected aircraft speeds','They are based only on runway length','Cloud clearance is unrelated to collision avoidance','The values exist only to simplify weather reports'],0,'Weather minima support visibility, reaction time, and separation from IFR traffic emerging from clouds in different operating environments.','VFR weather minima','Purpose'),
Q('A pilot is exactly at a cloud-clearance minimum but visibility is deteriorating and terrain is rising. Is continuing automatically a good decision?', ['No; regulatory minima are not personal safety margins, and terrain, proficiency, weather trend, and escape options must also be considered','Yes; meeting the numeric minimum guarantees safety','Yes if GPS is installed','No only if ATC objects'],0,'Legal minima are thresholds, not a complete risk assessment.','VFR weather minima','Legal versus safe'),
Q('Why is the lateral “shelf” structure of Class B important to VFR pilots?', ['Different floors exist at different distances from the primary airport, so a pilot can be outside or underneath Class B depending on altitude and position','Class B always begins at the surface everywhere','Shelves apply only to IFR aircraft','A shelf is a runway extension'],0,'Class B is individually tailored with surface areas and shelves; pilots must interpret charted floors/ceilings.','Controlled airspace','Class B shelves'),
Q('A VFR pilot remains below a Class B shelf. What must the pilot still consider?', ['Other airspace, transponder/ADS-B requirements, cloud clearance, terrain, and local procedures can still apply','Being below the shelf removes all regulations','ATC services become prohibited','The pilot may climb into Class B without clearance if near the edge'],0,'Avoiding one airspace boundary does not eliminate other regulatory or operational requirements.','Controlled airspace','Airspace layering'),
Q('What is a prohibited area?', ['Airspace within which flight is prohibited for security or national-welfare reasons unless specifically authorized','Airspace where VFR pilots may fly freely with caution','A military training area only','An airport traffic area'],0,'Prohibited areas bar flight for specified reasons except as authorized.','Special use airspace','Prohibited area'),
Q('What is a restricted area?', ['Airspace containing unusual, often invisible hazards where flight is subject to restrictions when active','Airspace in which all civilian flight is permanently prohibited','A weather advisory region','Any Class D surface area'],0,'Restricted areas can contain artillery, missiles, or other hazards and require status/authorization considerations.','Special use airspace','Restricted area'),
Q('A VFR pilot’s route crosses a military operations area (MOA). What is the correct general approach?', ['Determine its status and exercise extreme caution; VFR flight is not automatically prohibited, but high-speed military activity may be present','MOAs are always closed to VFR aircraft','Ignore the MOA because military traffic is separated from all VFR traffic','Enter only after receiving a Class B clearance'],0,'MOAs separate certain military training from IFR traffic and alert VFR pilots to potentially hazardous activity; VFR entry is generally not prohibited by the MOA designation itself.','Special use airspace','MOA'),
Q('What is the purpose of an alert area?', ['Warn pilots of a high volume of pilot training or unusual aerial activity, with all participants sharing collision-avoidance responsibility','Prohibit all VFR flight','Protect the President','Contain artillery firing'],0,'Alert areas advise of concentrated or unusual flight activity rather than imposing a general prohibition.','Special use airspace','Alert area'),
Q('What is a warning area?', ['Airspace of defined dimensions extending from three nautical miles outward from the U.S. coast containing activity that may be hazardous to nonparticipating aircraft','A prohibited area over every airport','A weather-only advisory','A temporary Class B shelf'],0,'Warning areas identify potentially hazardous activity over domestic/international waters where U.S. jurisdiction is limited.','Special use airspace','Warning area'),
Q('What is a Temporary Flight Restriction (TFR)?', ['A time-limited restriction on flight in a defined area for specified reasons published through NOTAMs','A permanent Class A boundary','A runway closure marking only','An advisory that can always be ignored in VMC'],0,'TFRs establish temporary flight restrictions for events such as security, disasters, space operations, or other specified purposes.','Other airspace','TFR'),
Q('Why must pilots check current NOTAMs for TFRs even when using a current sectional chart?', ['TFRs can be created or changed after the chart was published','Every TFR is printed permanently on sectionals','NOTAMs apply only to IFR flights','Sectionals update continuously in real time'],0,'Time-sensitive airspace restrictions are distributed via NOTAM systems rather than waiting for chart publication cycles.','Other airspace','TFR currency'),
Q('A pilot sees a magenta vignette indicating Class E begins at 700 feet AGL. What is the operational significance below 700 feet, assuming no other controlled airspace?', ['The airspace below is generally Class G, with different VFR minima/services than Class E','The area below is Class B','The area below is prohibited','Class E begins at the surface instead'],0,'A 700-foot Class E transition area leaves Class G below until the Class E floor.','Controlled airspace','Class E floor'),
Q('A dashed magenta line surrounds an airport on a sectional. What does it generally depict?', ['Class E airspace beginning at the surface','Class D airspace','A prohibited area','A Class B shelf'],0,'Dashed magenta boundaries identify Class E surface areas designated for an airport.','Controlled airspace','Class E surface area'),
Q('A dashed blue line surrounds an airport on a sectional. What does it generally depict?', ['Class D airspace','Class E surface area','Class B airspace','An MOA'],0,'Dashed blue lines depict Class D surface areas.','Controlled airspace','Class D charting'),
Q('Solid blue concentric boundaries around a major airport generally depict what?', ['Class B airspace','Class C airspace','Class G airspace','A restricted area'],0,'Class B is charted with solid blue lines.','Controlled airspace','Class B charting'),
Q('Solid magenta boundaries around an airport generally depict what?', ['Class C airspace','Class B airspace','Class D airspace','A TFR'],0,'Class C is typically charted with solid magenta boundaries.','Controlled airspace','Class C charting'),
Q('Why is knowing both airspace class and altitude essential before a VFR flight?', ['Communication/equipment requirements and weather minima can change when crossing a floor, ceiling, or time/altitude threshold','Airspace requirements depend only on latitude','All VFR rules are identical in every class','Altitude matters only for oxygen rules'],0,'Airspace is three-dimensional; a route can cross multiple classes and floors even while following the same ground track.','Airspace planning','Three-dimensional airspace'),
Q('A pilot is flying near the edge of controlled airspace using GPS. Why should the pilot still cross-check the sectional and position carefully?', ['GPS can show position, but the pilot must understand the charted boundary, altitude limits, database currency, and navigation accuracy','GPS automatically issues all required clearances','Airspace boundaries move to match GPS tracks','Sectionals are unnecessary with moving maps'],0,'Navigation equipment does not replace understanding or compliance with charted airspace.','Airspace planning','Moving-map limitations'),
Q('A pilot plans to transit a Special Flight Rules Area or other specially regulated area. What should be assumed?', ['Special procedures, training, equipment, routing, or clearances may apply beyond ordinary class-of-airspace rules','Normal Class G rules always override special rules','A sectional symbol is enough; no current procedure needs review','Special areas apply only to airlines'],0,'Some areas have special regulatory procedures that must be reviewed in current FAA sources.','Other airspace','Special flight rules'),
Q('What is the practical difference between controlled and uncontrolled airspace for a VFR pilot?', ['Controlled airspace has defined ATC services and regulatory structure, but VFR pilots still retain see-and-avoid responsibilities; uncontrolled Class G has different service/minimum structures','ATC guarantees separation of all VFR aircraft in all controlled airspace','Class G has no regulations','Controlled airspace always requires a clearance'],0,'“Controlled” does not mean ATC provides separation between all VFR aircraft; requirements and services vary by class.','Airspace concepts','Controlled versus uncontrolled'),
Q('A pilot receives VFR flight following while outside Class B. Does that service itself authorize entry into Class B?', ['No; a specific Class B clearance is still required','Yes; radar contact automatically clears Class B entry','Yes if a discrete transponder code is assigned','Only at night'],0,'Radar advisory service and Class B entry clearance are distinct.','ATC services','Flight following versus clearance'),
Q('A pilot is receiving radar traffic advisories in Class E. Who remains responsible for avoiding other VFR traffic?', ['The pilot remains responsible for see-and-avoid even while receiving advisories','ATC assumes all collision-avoidance responsibility','The nearest IFR aircraft','The airport operator'],0,'Advisories supplement, rather than replace, the pilot’s visual collision-avoidance responsibility in VMC.','ATC services','See and avoid'),
Q('Why should pilots avoid memorizing one set of VFR weather minima without context?', ['The applicable values depend on airspace class, altitude, day/night in some Class G cases, and specific operating rules','All minima are 3 miles and 500-1,000-2,000 everywhere','Weather minima depend only on aircraft weight','Minima never change above 10,000 feet'],0,'VFR minima are conditional; pilots must identify the actual airspace and altitude/time situation.','VFR weather minima','Context dependence'),
Q('What is the best operational summary of airspace knowledge?', ['Before flight, trace the route in three dimensions, identify every class/special-use/TFR boundary, and know the communication, equipment, weather, and clearance requirements before reaching it','Memorize airspace colors without route planning','Assume GPS will warn before every violation','Treat all controlled airspace as requiring the same clearance'],0,'Safe airspace operation requires preflight planning plus continuous positional and altitude awareness.','Airspace planning','Operational synthesis')
]

chapters[16]=[
Q('A pilot navigates by matching lakes, highways, and towns outside the window to a sectional chart. Which navigation method is being used?', ['Pilotage','Dead reckoning','VOR interception only','Inertial navigation'],0,'Pilotage is navigation by reference to visible landmarks.','Navigation methods','Pilotage'),
Q('A pilot computes heading, groundspeed, time, and distance from a known position without relying on visible landmarks. Which method is being used?', ['Dead reckoning','Pilotage','Radar vectors','Visual approach only'],0,'Dead reckoning uses known position plus direction, time, speed, and wind calculations.','Navigation methods','Dead reckoning'),
Q('Why is it safer to combine pilotage, dead reckoning, and electronic navigation rather than rely on a single source?', ['Independent methods cross-check one another and provide backup if visibility, equipment, or data fails','Using multiple methods creates unavoidable conflicting positions','Electronic navigation is legally prohibited with pilotage','Dead reckoning works only at night'],0,'Redundancy improves situational awareness and helps detect errors before they become large.','Navigation methods','Cross-checking'),
Q('What makes a good VFR checkpoint?', ['A prominent, unique feature near the route that is easy to identify from the air','A small feature that looks like many others','A point directly under busy Class B airspace regardless of visibility','Any feature that appears on an online road map'],0,'Useful checkpoints should be distinctive, visible, and spaced to support timely position verification.','Flight planning','Checkpoints'),
Q('A pilot’s true course is 090° and wind pushes the airplane south of course. What general heading correction is required?', ['Crab into the wind, toward the north of the desired course','Turn farther south','Maintain 090° because heading and course are identical','Change magnetic variation'],0,'A wind-correction angle points the aircraft into the crosswind so the resultant ground track follows the desired course.','Wind correction','Wind correction angle'),
Q('What is the difference between heading and course?', ['Heading is where the nose points; course is the intended or actual path over the Earth','They are always identical','Course is measured only from magnetic north and heading only from true north','Heading is groundspeed'],0,'Wind can make the aircraft’s heading differ from its ground track/course.','Navigation concepts','Heading versus course'),
Q('What is groundspeed?', ['The aircraft’s speed relative to the Earth’s surface','Indicated airspeed corrected for instrument error only','The speed of the propeller tip','True airspeed relative to the airmass'],0,'Groundspeed is the rate of movement over the ground and is the result of true airspeed plus the wind vector.','Navigation concepts','Groundspeed'),
Q('A 120-knot true-airspeed airplane has a 20-knot direct headwind. Ignoring other effects, what is groundspeed?', ['100 knots','120 knots','140 knots','60 knots'],0,'A direct 20-knot headwind subtracts from 120-knot TAS, giving approximately 100-knot groundspeed.','Wind correction','Groundspeed','advanced','calculation'),
Q('At 100 knots groundspeed, approximately how far does an airplane travel in 18 minutes?', ['30 NM','18 NM','60 NM','300 NM'],0,'18 minutes is 0.3 hour; 100 × 0.3 = 30 NM.','Flight planning','Time-distance','advanced','calculation'),
Q('An airplane must fly 150 NM at a planned groundspeed of 100 knots. What is estimated time en route?', ['1 hour 30 minutes','1 hour','2 hours 30 minutes','50 minutes'],0,'Time = distance ÷ groundspeed = 150/100 = 1.5 hours.','Flight planning','ETE','advanced','calculation'),
Q('The airplane burns 9 gallons per hour and planned ETE is 2.0 hours. Before adding reserve/taxi allowances, how much cruise fuel is required?', ['18 gallons','9 gallons','4.5 gallons','27 gallons'],0,'Fuel = burn rate × time = 9 × 2 = 18 gallons.','Flight planning','Fuel calculation','advanced','calculation'),
Q('Why should actual groundspeed and fuel burn be compared with the flight plan after departure?', ['Unexpected wind or performance differences can change ETA and fuel reserve, requiring an early update or diversion','The original plan cannot be changed once airborne','Groundspeed has no effect on fuel remaining','Only ATC may revise an ETA'],0,'A flight plan is a prediction; in-flight checks detect deviations while alternatives remain available.','Flight planning','In-flight replanning'),
Q('What is true course?', ['The intended direction of flight measured from true north','The compass indication after deviation correction only','The aircraft nose direction relative to magnetic north','The radial from a VOR'],0,'True course is referenced to true north and is converted through variation/wind corrections to a usable heading.','Navigation concepts','True course'),
Q('What correction converts between true and magnetic directions?', ['Magnetic variation','Compass deviation','Wind correction angle','Density altitude'],0,'Variation is the angular difference between true north and magnetic north at a geographic location.','Navigation concepts','Variation'),
Q('What correction accounts for magnetic error caused by the airplane itself?', ['Compass deviation','Magnetic variation','Wind correction','Pressure altitude'],0,'Deviation is aircraft-specific compass error caused by onboard magnetic/electrical influences.','Navigation concepts','Deviation'),
Q('Why is a current sectional chart important even when using GPS?', ['It depicts airspace, obstacles, airports, frequencies, terrain, and charted information the pilot must understand independently of the navigator','GPS automatically contains every current NOTAM and TFR','Sectionals are used only for pilotage exams','GPS position makes airspace knowledge unnecessary'],0,'Electronic position is only one part of navigation; pilots still need current aeronautical context and should verify database/current information.','Aeronautical charts','Sectional chart'),
Q('What is the practical purpose of the Chart Supplement during cross-country planning?', ['Obtain airport/facility details such as runway data, frequencies, services, remarks, and procedures not fully shown on the sectional','Calculate wing loading','Determine engine compression','Replace all NOTAMs'],0,'The Chart Supplement provides detailed facility information that complements charts and current NOTAMs.','Flight planning','Chart Supplement'),
Q('A pilot selects checkpoints 50 miles apart in hazy terrain with few landmarks. What planning weakness does this create?', ['Position errors may grow too large between verifications; closer or more distinctive checkpoints/backup navigation may be needed','Long checkpoint spacing always improves accuracy','Checkpoints are unnecessary below 10,000 feet','It automatically improves groundspeed'],0,'Checkpoint choice should support timely position awareness under expected visibility and terrain conditions.','Flight planning','Checkpoint spacing'),
Q('A pilot is 5 NM off course after flying 30 NM and still has 60 NM to go. Using the 1-in-60 concept, approximately how large is the track error so far?', ['About 10°','About 2°','About 30°','About 60°'],0,'A displacement of 1 NM after 60 NM is about 1°. Five miles off after 30 NM is roughly 5/30 × 60 ≈ 10°.','Dead reckoning','1-in-60 rule','advanced','calculation'),
Q('Using the situation of being 5 NM off course after 30 NM with 60 NM remaining, why must a pilot correct by more than the original track-error angle to regain course?', ['The pilot must both stop further divergence and intercept back to the desired course over the remaining distance','The original error automatically disappears','Only magnetic variation needs correction','A correction smaller than the error always intercepts faster'],0,'A closing angle is needed in addition to the correction that would merely parallel the desired course.','Dead reckoning','Course correction','advanced'),
Q('What does a VOR radial represent?', ['A magnetic course extending outward FROM the VOR station','A true bearing toward the station only','A GPS airway','The aircraft’s heading'],0,'VOR radials are defined outward from the station and are referenced to magnetic north at the station.','Radio navigation','VOR radial'),
Q('A CDI centers with a FROM indication and 090 selected. What position relationship is indicated, assuming a valid VOR signal?', ['The aircraft is on or near the 090 radial from the station','The aircraft is necessarily eastbound toward the station','The aircraft is on the 270 radial','The station is directly behind the tail regardless of heading'],0,'With 090 selected and FROM, the centered course corresponds to the 090 radial. The aircraft heading can be different.','Radio navigation','VOR interpretation','advanced'),
Q('A CDI centers with a TO indication and 090 selected. What course would take the aircraft toward the station if wind were ignored?', ['090° magnetic course toward the station','270° away from the station','Any heading because TO means over the station','The aircraft is on the 090 radial FROM the station'],0,'A centered 090 course with TO indicates the selected 090 course leads to the station; the reciprocal radial is associated with the aircraft position.','Radio navigation','VOR TO indication','advanced'),
Q('Why can a VOR indication become unreliable near station passage?', ['The angular geometry changes rapidly and the cone of confusion can produce unstable indications','The station stops transmitting every time an aircraft passes overhead','VORs work only beyond 40 NM','Magnetic variation becomes zero'],0,'Near/over the station, course/radial indications can swing rapidly as the aircraft passes through the cone of confusion.','Radio navigation','VOR station passage'),
Q('Why should a pilot verify VOR receiver accuracy when required before IFR use and also understand its limitations for VFR navigation?', ['Navigation receivers can have error or fail; confidence in the equipment depends on proper checks and cross-checking','VOR signals are always exact and self-verifying','Only GPS requires accuracy checks','A VOR check changes magnetic variation'],0,'Navigation equipment is not infallible; approved checks and cross-validation support reliable use.','Radio navigation','VOR accuracy'),
Q('What is a major strength of GPS navigation?', ['Continuous precise position and course information independent of nearby ground stations within system/receiver limits','It guarantees terrain and weather clearance','It never depends on database currency','It removes the need to understand airspace'],0,'GPS provides highly accurate satellite-derived position/navigation, but safe use still requires current databases, integrity awareness, and pilot cross-check.','GPS','GPS strengths'),
Q('Why can blindly following a magenta GPS line be unsafe?', ['The programmed route may be wrong or may intersect terrain, airspace, weather, or an unsuitable waypoint; the pilot must validate it against the flight plan and current conditions','GPS routes are automatically cleared by ATC','The magenta line always accounts for current TFRs','Terrain cannot exist on a direct route'],0,'Automation can accurately fly an incorrect plan; pilots must verify route, data, and context.','GPS','Automation trap'),
Q('What does “direct-to” navigation change compared with the original planned route?', ['It creates a new course from present position to the selected waypoint, which may bypass planned checkpoints or airspace/terrain margins','It preserves every segment of the original route','It automatically receives ATC clearance','It changes the aircraft’s true airspeed'],0,'Direct-to simplifies routing but can invalidate the assumptions and checkpoints of the original plan.','GPS','Direct-to'),
Q('A pilot loses GPS during a VFR cross-country. What preparation most improves resilience?', ['Maintain chart awareness, headings, checkpoints, time/fuel estimates, and the ability to use pilotage/dead reckoning or other available navigation','Rely on the last GPS position indefinitely','Descend until a highway appears regardless of terrain','Assume ATC will always be available'],0,'Navigation redundancy and continuous position awareness prevent a single equipment failure from becoming an emergency.','Navigation methods','GPS failure'),
Q('What is the best operational summary of VFR navigation?', ['Plan the route, wind, fuel, time, airspace, terrain, and checkpoints; then continuously compare actual position/performance with the plan and replan early when they diverge','Follow the GPS line and ignore paper/chart context','Calculate heading once and never update it','Use pilotage only, because electronic navigation reduces skill'],0,'Safe navigation is a continuous closed-loop process: plan, fly, verify, and update.','Flight planning','Operational synthesis')
]

chapters[17]=[
Q('A pilot at altitude develops headache, euphoria, poor judgment, and increasing difficulty with simple tasks. What should be suspected first?', ['Hypoxia','Motion sickness only','Hyperglycemia','Magnetic disorientation'],0,'Hypoxia often impairs judgment before the pilot fully recognizes the problem; symptoms can include headache, euphoria, visual changes, and poor coordination.','Hypoxia','Recognition'),
Q('What is the most appropriate immediate response to suspected hypoxia in flight?', ['Use supplemental oxygen if available and descend to a lower altitude as conditions permit','Climb to get above the weather','Increase cabin heat only','Drink caffeine and continue'],0,'Restoring oxygen availability and reducing altitude exposure are the key immediate actions.','Hypoxia','Response'),
Q('Why is hypoxia especially insidious for pilots?', ['It can degrade judgment and create a sense of well-being, reducing the pilot’s ability to recognize impairment','It always causes immediate severe pain','It affects only passengers','It cannot occur in pressurized aircraft'],0,'The organ needed to detect and solve the problem—the brain—is itself impaired.','Hypoxia','Insidious nature'),
Q('Hypoxic hypoxia at altitude is primarily caused by what?', ['Reduced oxygen partial pressure available for gas exchange','Blood loss only','Carbon monoxide binding only','Cells being unable to use oxygen because of alcohol'],0,'As atmospheric pressure falls, oxygen partial pressure falls even though oxygen percentage remains roughly constant.','Hypoxia','Hypoxic hypoxia'),
Q('Carbon monoxide exposure is an example of which hypoxia mechanism?', ['Hypemic hypoxia because hemoglobin’s oxygen-carrying capacity is reduced','Stagnant hypoxia only','Histotoxic hypoxia only','No hypoxia mechanism'],0,'Carbon monoxide binds strongly to hemoglobin and reduces the blood’s ability to carry oxygen.','Hypoxia','Hypemic hypoxia'),
Q('A pilot with poor circulation from shock has oxygenated blood but inadequate blood flow to tissues. Which hypoxia type fits best?', ['Stagnant hypoxia','Hypoxic hypoxia','Histotoxic hypoxia','No hypoxia'],0,'Stagnant hypoxia results when circulation is insufficient to deliver available oxygen effectively.','Hypoxia','Stagnant hypoxia'),
Q('Alcohol can contribute to which hypoxia category by interfering with cells’ ability to use oxygen?', ['Histotoxic hypoxia','Hypoxic hypoxia only','Stagnant hypoxia only','None'],0,'Histotoxic hypoxia occurs when tissues cannot effectively use delivered oxygen; certain toxins and alcohol can contribute.','Hypoxia','Histotoxic hypoxia'),
Q('A pilot is anxious and breathing rapidly, then develops tingling, lightheadedness, and visual symptoms. What is a likely cause?', ['Hyperventilation','Carbon monoxide poisoning only','Dehydration only','Hypothermia only'],0,'Excessive ventilation can reduce carbon dioxide levels and cause symptoms that can resemble hypoxia.','Respiration','Hyperventilation'),
Q('Why can hyperventilation and hypoxia be difficult to distinguish in flight?', ['They share symptoms such as lightheadedness, tingling, visual disturbance, and impaired performance','Hyperventilation has no symptoms','Hypoxia always causes chest pain only','Only one occurs above sea level'],0,'The overlap in symptoms means pilots should use context and safe corrective actions rather than relying on a single symptom.','Respiration','Differential recognition'),
Q('What is the recommended general response to suspected hyperventilation when oxygen is otherwise adequate?', ['Consciously slow and regulate breathing while reducing stress and workload; use oxygen if hypoxia cannot be ruled out','Breathe as rapidly as possible','Climb to higher altitude','Hold the breath until unconscious'],0,'Reducing ventilation toward a normal pattern can restore carbon dioxide balance; if hypoxia is possible, oxygen/descent should also be considered.','Respiration','Hyperventilation response'),
Q('A cabin-heater exhaust leak introduces carbon monoxide. Why may the pilot fail to recognize it quickly?', ['Carbon monoxide is colorless and odorless and can cause headache, drowsiness, confusion, and impaired judgment','It always smells strongly of fuel','It affects only the engine','It produces an immediate visible cloud'],0,'CO provides little sensory warning and impairs cognition, making detection difficult without a detector or symptom awareness.','Carbon monoxide','Recognition'),
Q('What is the best immediate response to suspected carbon monoxide contamination in a piston airplane?', ['Shut off the suspected cabin-heat source/ventilate as appropriate, use oxygen if available, and land as soon as practical according to the situation','Increase cabin heat to burn off the gas','Climb as high as possible','Close all fresh-air vents'],0,'The priorities are to stop exposure, increase fresh air/oxygen, and terminate the flight safely.','Carbon monoxide','Response'),
Q('A VFR pilot accidentally enters cloud and feels the airplane is turning even though the instruments show straight-and-level. What should the pilot trust?', ['Properly functioning flight instruments, not the vestibular sensation','The body sensation because it is more immediate','The magnetic compass alone for attitude','Passenger perception'],0,'Without reliable visual references, the vestibular system can create powerful false sensations; instruments provide the dependable attitude reference.','Spatial disorientation','Instrument reliance'),
Q('What produces the “leans”?', ['A slow unnoticed bank followed by a correction can make level flight feel like a bank in the opposite direction','A rapid change in cabin pressure','Carbon monoxide only','A visual approach to a narrow runway'],0,'The semicircular canals may not detect a gradual turn; returning to level can then be perceived as a turn the other way.','Spatial disorientation','Leans'),
Q('What is a graveyard spiral?', ['A prolonged coordinated turn mistaken for level flight, followed by a tightening descending spiral when the pilot tries to correct perceived altitude loss by pulling back','A stall caused by too much rudder during takeoff','A spin entered only at night','A visual illusion from a narrow runway'],0,'In a sustained turn the vestibular system can adapt; pulling to stop the descent without correcting bank tightens the spiral.','Spatial disorientation','Graveyard spiral'),
Q('Why is a graveyard spiral not the same as a spin?', ['A graveyard spiral is a high-speed descending turn with the wing generally not stalled; a spin involves a stalled wing and autorotation','Both are identical aerodynamic states','A graveyard spiral occurs only on the ground','A spin always has higher airspeed'],0,'The recovery priorities differ because the aerodynamic states are different.','Spatial disorientation','Spiral versus spin','advanced'),
Q('A dark night approach is made over featureless terrain with few lights. Which illusion can cause the pilot to fly too low?', ['Black-hole approach illusion','False horizon only','Autokinesis only','Runway-width illusion only'],0,'Without normal peripheral visual cues, a pilot can perceive being high and descend below a safe glidepath.','Visual illusions','Black-hole approach'),
Q('A runway is much narrower than the pilot is used to. What visual illusion may occur on final?', ['The pilot may perceive being higher than actual and fly a lower-than-normal approach','The pilot will always perceive being too low','Runway width has no effect on visual perception','The horizon will rotate'],0,'A narrow runway can appear farther away/higher perspective, causing a tendency toward a low approach.','Visual illusions','Runway-width illusion'),
Q('A runway is much wider than the pilot is used to. What visual illusion may occur?', ['The pilot may perceive being lower than actual and fly a higher-than-normal approach','The pilot will always land short','The runway appears narrower','No illusion is possible'],0,'A wide runway can create the impression of being lower than actual, encouraging a high approach.','Visual illusions','Runway-width illusion'),
Q('What is a false horizon?', ['Cloud formations, sloping terrain, lights, or other visual cues are mistaken for the true horizon, leading to incorrect attitude control','A magnetic compass error only','A GPS database issue','A runway lighting failure'],0,'Visual references can create an apparent horizon that is tilted or displaced from the actual one.','Visual illusions','False horizon'),
Q('What is autokinesis?', ['A stationary light viewed in darkness can appear to move after prolonged fixation','The sensation of climbing during acceleration','A compass turning error','The eye adapting to bright light'],0,'Without surrounding visual references, small involuntary eye movements can make a fixed light seem to move.','Visual illusions','Autokinesis'),
Q('Why should a pilot avoid staring at a single light at night?', ['Peripheral scanning and changing fixation reduce autokinesis and improve detection of dim objects','Staring improves depth perception indefinitely','The light can magnetize the compass','It increases oxygen saturation'],0,'Night vision benefits from scanning and off-center viewing rather than prolonged central fixation.','Vision','Night scanning'),
Q('Why is off-center viewing useful at night?', ['The retina’s rod cells, which are more sensitive in dim light, are concentrated away from the fovea','The fovea contains all rod cells','Peripheral vision has no night advantage','It prevents hyperventilation'],0,'Looking slightly away from a dim object places its image on rod-rich areas of the retina.','Vision','Off-center viewing'),
Q('Why can bright cockpit lighting degrade night vision?', ['It reduces dark adaptation, especially of rod vision, making dim external objects harder to see','It improves rod sensitivity','It prevents spatial disorientation completely','It increases oxygen partial pressure'],0,'Dark adaptation takes time and is degraded by bright light exposure.','Vision','Dark adaptation'),
Q('What is the IMSAFE checklist intended to evaluate?', ['Illness, Medication, Stress, Alcohol, Fatigue, and Emotion/Eating factors affecting personal fitness','Aircraft maintenance items','Weather minimums','Airport signage'],0,'IMSAFE is a personal preflight self-assessment tool for physiological and psychological fitness.','Fitness for flight','IMSAFE'),
Q('A pilot took a new over-the-counter medication and feels normal. What is the safest decision process?', ['Determine the medication’s aeromedical effects and compatibility with flying before acting as a crewmember, rather than assuming nonprescription means safe','Fly because over-the-counter drugs have no side effects','Take a double dose to test tolerance','Use caffeine to cancel any drowsiness'],0,'Many common medications can impair alertness, reaction time, vision, or judgment; pilots must consider both the illness and the medication.','Medication','Medication risk'),
Q('Why is fatigue dangerous even when a pilot can “push through” it subjectively?', ['Fatigue degrades attention, reaction time, memory, judgment, and error detection, often before the pilot accurately recognizes the extent','Fatigue affects only muscle strength','Fatigue improves risk tolerance','Fatigue matters only on flights longer than eight hours'],0,'Fatigue produces broad cognitive impairment and can also reduce self-awareness of that impairment.','Fatigue','Performance effects'),
Q('A pilot completed a scuba dive and plans to fly soon afterward. What is the concern?', ['Reduced atmospheric pressure at altitude can promote decompression sickness, so appropriate no-fly intervals should be observed','Flying increases oxygen pressure and eliminates decompression risk','Scuba affects only hearing','Cabin heat removes dissolved nitrogen'],0,'Flying after diving can allow dissolved inert gas to form bubbles as ambient pressure falls.','Decompression','Scuba diving'),
Q('A pilot feels ear or sinus pain during descent after flying with congestion. What mechanism is most likely?', ['Pressure cannot equalize adequately across blocked passages as ambient pressure rises','Oxygen percentage increases too quickly','The magnetic compass is affected','The pitot tube is blocked'],0,'Blocked Eustachian tubes or sinus passages can prevent pressure equalization and cause barotrauma.','Pressure effects','Ear and sinus block'),
Q('What is the best operational summary of aeromedical knowledge?', ['Use a disciplined fitness check before flight, recognize early physiological/visual-disorientation symptoms, and take conservative action before impairment erodes the ability to decide','Assume a valid medical certificate guarantees fitness on the day of flight','Treat discomfort as something to ignore until landing','Rely on passengers to detect pilot impairment'],0,'Day-of-flight fitness and symptom recognition are continuous pilot responsibilities, regardless of certificate status.','Aeromedical factors','Operational synthesis')
]

# Build normalized assessment records and write files.
for ch in range(1,18):
    qs=chapters.get(ch,[])
    out=[]
    for idx,item in enumerate(qs,1):
        rec={
            'id':f'CH{ch:02d}-V1-{idx:02d}',
            'chapter':ch,
            'topic':item['topic'],
            'subtopic':item['section'],
            'difficulty':item['difficulty'],
            'type':item['type'],
            'prompt':item['prompt'],
            'choices':item['choices'],
            'correctIndex':item['correctIndex'],
            'explanation':item['explanation'],
            'sourcePage':f'FAA-H-8083-25C, Chapter {ch} — {item["section"]}',
            'learningObjective':f'Apply {item["section"]} knowledge to a realistic pilot decision or flight condition.',
            'family':f'ch{ch:02d}-{idx:02d}'
        }
        out.append(rec)
    (ROOT/f'chapter-{ch:02d}.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')

print({ch:len(chapters.get(ch,[])) for ch in range(1,18)})
